window.COURSE = {"id": "cs329z", "code": "CS329Z", "title": "AI 智能体工程", "subtitle": "Engineering AI Agents · 从工具调用到可评估系统", "description": "19讲Agent系统工程社区学习路径，覆盖检索、工具、记忆、编排、数据、评测与编码工作流。每讲有独立可运行实验、具体系统案例和情境自测；已公开课程材料与社区预习清楚区分。", "year": "2026 秋季", "sourceUrl": "https://cs329z.stanford.edu/", "instructors": ["Diyi Yang", "Michael Ryan", "John Yang"], "prerequisites": ["能编写和调试Python程序，理解函数、数据结构与基本测试。", "具备语言模型与深度学习基础；可先学习CS336的模型与训练章节。", "熟悉API、JSON和Git；运行官方作业通常需要本地Python环境，部分作业需要Docker及模型API。"], "modules": [{"id": "foundations", "title": "01 · 基础与构建模块", "description": "先理解任务与模型，再搭建检索、工具和编排。"}, {"id": "agent-design", "title": "02 · 智能体设计与优化", "description": "把行动、记忆、协作与优化组织成可控系统。"}, {"id": "data-evaluation", "title": "03 · 数据与可靠评测", "description": "从轨迹和终端任务出发，建立有证据的迭代闭环。"}, {"id": "deployment", "title": "04 · 前沿专题与部署预习", "description": "对应官方尚未公开课件的后续课程，提供明确标注的原创预习。"}], "lessons": [{"id": "01", "module": "foundations", "title": "从语言模型到智能体系统", "originalTitle": "Introduction — What Are Agentic Systems?", "summary": "用有限状态控制器回放检查、补证据和验收，分清有预算、字段齐全与真正完成之间的差别。", "objectives": ["区分单次生成、固定工作流与自主决策循环", "把模糊需求转成可观察的成功条件", "识别系统层面的可靠性和成本问题"], "sections": [{"title": "先定义任务，再选择自主程度", "body": "假设用户希望整理一组会议记录。固定流程可以依次读取、抽取行动项、检查字段、导出表格。如果记录位置未知，或不同文件需要不同处理步骤，系统才可能需要根据观察结果选择下一步。智能体的关键是对环境采取动作并利用反馈继续决策；仅仅把多个提示词串起来，并不能说明系统需要自主探索。设计时先写出输入、允许的动作、输出验收条件，再决定哪些分支交给模型。", "bullets": ["固定工作流适合路径稳定、规则明确的任务。", "智能体适合需要观察、探索和动态纠错的任务。", "自主程度越高，需要越清楚的边界与停止规则。"]}, {"title": "画出一次完整的交互", "body": "把模型看作策略的一部分：它接收当前任务和可用信息，提出动作；执行器验证动作并调用工具；环境返回观察；系统记录状态并再次决策。状态不仅是聊天历史，还包括已完成步骤、预算、文件版本和错误信息。例如查询订单后才能判断是否可以退款，工具返回的订单状态应进入后续决策，不能让模型凭印象填补。", "bullets": ["模型决定建议做什么，程序决定什么被允许执行。", "工具失败也是观察，必须进入下一轮状态。", "完成状态要由可检查的结果支持。"]}, {"title": "系统效果取决于最弱环节", "body": "优秀的模型也会被缺失资料、错误工具描述或不稳定评分拖累。若三个顺序步骤的成功率均为0.9，在独立假设下整条链的成功率只有0.729；真实错误还可能相关。用少量代表性任务建立基线，逐条阅读失败轨迹，区分知识不足、行动错误和环境故障。把成功率、人工介入次数、延迟和费用一起记录，才能判断复杂系统是否值得。", "bullets": ["先做一个可工作的最小闭环。", "按故障类型改进组件，避免只修改提示词。", "独立性只是计算例子的假设，不是实际系统的保证。"], "formula": "P(全部步骤成功) = ∏ᵢ pᵢ （仅在各步骤成功事件独立时）"}, {"kind": "worked-example", "title": "逐步回放：调用2次以后为什么仍不能宣布完成", "body": ["定义一份内存草稿{title:\"Summary\",source:null}，本地证据表只有有效来源S1。验收条件是标题非空且source能在证据表中解析。每个工具动作耗1次预算：inspect观察草稿，发现缺source后转到needs_source；lookup_source返回S1并填入字段，转到needs_validation；validate才计算验收条件，并把verified设为true或false。控制器没有调用真实模型，专门用可见状态展示契约。", "预算3时依次执行inspect、lookup_source、validate，调用数3、余量0，最终complete且verified=true。预算2时source虽然已经是S1，却还没有运行验证器，最终必须是budget_exhausted、verified=false，保存待验证状态供恢复。预算5时仍只执行3次，验收成功后立刻停止，剩余2次不必用完。这个差别说明“工具成功返回”“字段看起来齐全”和“满足任务验收”是不同事件；状态与观察应一起保留在轨迹中。"], "formula": "complete ⇔ validate(draft)=true；执行前要求callsUsed<budget；预算2时verified=false", "bullets": ["误区：调用次数是资源消耗，不是完成证据；用完预算不能自动把结果标为成功。", "有限状态例子用于暴露可检查控制流，不声称实现了LLM自主规划，也没有真实文件或网络副作用。"]}], "exercise": {"title": "回放三个预算下的终止轨迹", "instructions": ["预测预算1、2、3时最后状态和草稿内容。", "运行后核对每次动作前后的状态与观察。", "把预算改成5，检查成功后是否立即停止。", "写出恢复预算2的任务时还缺哪一步，不重复已经完成的查证据动作。"], "deliverable": "三条事件轨迹、验收条件与可恢复状态说明"}, "quiz": [{"question": "预算2执行完inspect和lookup_source，草稿已含S1，但validate尚未执行。应该记录什么？", "options": ["budget_exhausted且verified=false", "complete，因为字段已填满", "complete，因为调用全部成功", "删除记录并假装任务未开始"], "answer": 0, "explanation": "只有验证器能设置verified=true。预算耗尽时应保存待验证状态并说明未完成，不能把字段齐全等同验收成功。"}, {"question": "同一任务预算从3增至5，前三次调用已通过验收。接下来最合理的行为是什么？", "options": ["继续调用两次以证明自主性", "停止并保留剩余2次预算", "把verified改回false重新开始", "不查看产物，只比较调用总数"], "answer": 1, "explanation": "预算是上限，完成条件已满足后应停止；额外调用并不自动增加可信度。"}], "resources": [{"title": "官方第1讲 · PDF第29页起 Agent anatomy；第56页工作流与智能体", "url": "https://web.stanford.edu/class/cs329z/slides/lecture01.pdf#page=29", "type": "pdf", "local": "materials/lecture01.pdf"}, {"title": "Zaharia et al. \"The Shift from Models to Compound AI Systems.\" BAIR Blog (2024).", "url": "https://bair.berkeley.edu/blog/2024/02/18/compound-ai-systems/", "type": "reading"}, {"title": "Weng. \"LLM Powered Autonomous Agents.\" Lil'Log (2023).", "url": "https://lilianweng.github.io/posts/2023-06-23-agent/", "type": "reading"}, {"title": "Kapoor et al. \"AI Agents That Matter.\" TMLR (2025).", "url": "https://arxiv.org/abs/2407.01502", "type": "reading"}], "sourceStatus": "published", "visual": "cs329z-01", "codeDemo": "cs329z-01"}, {"id": "02", "module": "foundations", "title": "给构建者的语言模型基础", "originalTitle": "LLMs for Builders", "summary": "把上下文限制转为完整证据包选择问题，预留输出并保留引用依赖，避免截断后无法核验。", "objectives": ["解释token、上下文和生成预算的关系", "区分格式约束与语义正确性", "为任务选择合适的推理与上下文策略"], "sections": [{"title": "模型生成的是条件分布", "body": "自回归语言模型根据前缀预测下一个token。温度和采样方式改变从分布取样的方式，因此同一请求可能产生不同结果。低温通常更集中，但不保证正确，也不能把所有系统的非确定性消除。应用应把解析失败、拒答、截断和空输出视为正常可处理的分支；使用记录下来的模型版本、参数和输入做可重复比较。", "bullets": ["训练学习分布，推理从分布生成序列。", "温度不等于事实准确率旋钮。", "结构化任务优先明确输出模式并做校验。"]}, {"title": "上下文窗口是工作空间", "body": "可放入上下文的token有上限，工具结果、对话、说明和模型输出共同消耗预算。长窗口不代表模型会同等关注所有片段。对于一个跨50份文档的任务，先检索相关证据、保留来源，再把过长观察压缩，比无差别塞入全文更容易诊断。压缩会丢信息，因此应保留原始文件位置，必要时重新读取。", "bullets": ["区分工作上下文与长期存储。", "重要约束、当前目标和待办状态应易于找到。", "检索与压缩都是选择信息，必须评估遗漏。"]}, {"title": "从生成到可靠接口", "body": "JSON Schema约束可以限制输出的形状，却不能证明订单号存在、日期合理或动作获准。可靠接口至少分三层：语法解析、字段与业务规则验证、权限检查。比如金额必须是数值且非负还不够，仍需确认货币、订单上限与调用者权限。扩大推理预算也有代价，应在相同任务集上比较质量提升是否覆盖额外延迟与费用。", "bullets": ["解析失败可有限重试，并保存原始错误。", "业务约束写在可测试代码里。", "用真实分布测量更多推理预算的收益。"]}, {"kind": "worked-example", "title": "手算：80token窗口为什么选两份小证据", "body": ["把预算人为设为80token：固定说明20、当前目标10、输出预留20，证据还可用30。三份证据包必须正文与引用一同保留：E1正文18+引用4，共22、价值8；E2正文12+引用4，共16、价值6；E3正文8+引用4，共12、价值4。这里的token数量与价值是教学给定值，不是对中文段落的真实分词或事实评分。", "枚举三个包的8种子集。E1+E2需38、E1+E3需34，都超证据预算30；E2+E3只需28，价值10，高于单独E1的价值8，所以选择E2与E3。输入总量30+28=58，加输出预留20后占78，剩余2。窗口75时证据预算25，只能选价值最高的单包E1；窗口100时证据预算50，三包可全部进入。若窗口仅40，固定需求50已经超限，应在请求前报告不可行，不能静默删掉用户约束或输出预留。"], "formula": "证据预算=80−20−10−20=30；E2+E3成本28、价值10；总预留78≤80", "bullets": ["误区：按正文长度截断后再补引用可能超预算；正文和来源属于同一依赖包，不能分开做账。", "预算可行与来源完整不保证回答质量；价值函数还需要独立任务数据来检验。"]}], "exercise": {"title": "完整证据包的预算验收", "instructions": ["手算三包8种组合，找到窗口80下的最优可行子集。", "运行窗口75、100与40，分别说明选择变化和不可行原因。", "为真实API用目标分词器替换人工计数，并核对其输入/输出限制。", "增加“E3依赖E1”的条件，说明枚举器应如何拒绝孤立E3。"], "deliverable": "子集成本/价值表、预算边界与依赖检查"}, "quiz": [{"question": "窗口80，固定输入30、输出预留20；E1占22价值8，E2占16价值6，E3占12价值4。应选哪组使价值最大？", "options": ["E2+E3", "E1+E2", "E1+E3", "三包全选"], "answer": 0, "explanation": "证据预算30。E2+E3占28、价值10；另外两组超过预算，单独E1只有价值8。"}, {"question": "窗口40，而固定说明、任务与输出预留共50。正确处理是什么？", "options": ["先发送请求，再期待模型自动修复", "静默删除所有引用", "将负的剩余预算记录成成功", "报告预算不可行，调整明确的需求后再构造请求"], "answer": 3, "explanation": "固定部分已超限，不能靠证据选择解决。应在请求前发现并明确调整，而不是隐式删掉关键约束。"}], "resources": [{"title": "官方第2讲 · PDF第160–171页 Context engineering", "url": "https://web.stanford.edu/class/cs329z/slides/lecture02.pdf#page=160", "type": "pdf", "local": "materials/lecture02.pdf"}, {"title": "Vaswani et al. \"Attention Is All You Need.\" NeurIPS (2017).", "url": "https://arxiv.org/abs/1706.03762", "type": "reading"}, {"title": "Katharopoulos et al. \"Transformers are RNNs: Fast Autoregressive Transformers with Linear Attention.\" ICML (2020).", "url": "https://arxiv.org/abs/2006.16236", "type": "reading"}, {"title": "Rajasekaran et al. \"Effective Context Engineering for AI Agents.\" Anthropic (2025).", "url": "https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents", "type": "reading"}], "sourceStatus": "published", "visual": "cs329z-02", "codeDemo": "cs329z-02"}, {"id": "03", "module": "foundations", "title": "检索增强生成：从文档到证据", "originalTitle": "Retrieval-Augmented Generation (RAG)", "summary": "从词频和文档频数真正计算BM25，再分别报告查询词覆盖、人工相关召回和引用忠实度。", "objectives": ["区分检索召回与回答忠实度", "解释稀疏、稠密和混合检索的适用性", "设计包含版本信息的证据引用"], "sections": [{"title": "索引决定能找到什么", "body": "RAG先把文档转成可搜索单元，再为用户问题选择相关证据。切块过小会破坏定义和条件，切块过大会带入噪声。对于制度文档，可以以小节为边界，给每块附上标题、发布日期、原文位置与权限标签。若新旧制度同时存在，内容相似度并不能决定哪一版适用；版本过滤应作为检索条件，而不只交给生成模型猜测。", "bullets": ["切块时保留标题与必要上下文。", "权限过滤必须覆盖索引与返回结果。", "记录文档版本，才能解释答案随时间变化的原因。"]}, {"title": "召回与排序是两个问题", "body": "BM25依赖词项匹配，适合型号、编号和专业术语；向量检索可发现语义近似表达，但可能漏掉精确约束。混合检索汇合候选后，用重排器比较问题与片段的相关性。评测时先问正确证据有没有进入候选集，再问是否被排到最终上下文；若第一步没有召回，增强生成模型无法修复信息缺口。", "bullets": ["Recall@k关注目标证据是否进入前k项。", "重排通常对较小候选集进行更昂贵的比较。", "增加k可能提升召回，也可能增加噪声与成本。"], "formula": "Recall@k = 检索前 k 项中的相关文档数 / 所有相关文档数"}, {"title": "生成必须接受证据约束", "body": "让模型先识别能支持回答的片段，再构造答案并给出引用。引用必须指向真实返回片段，并且该片段要支持对应结论。比如材料只说“试用期可申请”，答案不能扩张成“所有人自动获得”。当证据冲突或不足时，应指出缺少的条件，或再次检索。评估可以分别测证据相关性、答案正确性和陈述是否被引用支持。", "bullets": ["引用存在不等于引用支持结论。", "明确处理找不到资料与证据冲突。", "把检索失败和生成歪曲分开计数。"]}, {"kind": "worked-example", "title": "手算：查询词全覆盖，Recall却只有一半", "body": ["建立三份空格分词的教学文档：D1=\"refund policy refund\"长度3，D2=\"shipping policy\"长度2，D3=\"refund deadline policy deadline\"长度4，平均长度3。查询为refund与deadline，前者文档频数df=2，后者df=1。使用IDF(q)=ln[1+(N−df+.5)/(df+.5)]，两者分别ln1.6≈0.470004、ln(8/3)≈0.980829；BM25取k1=1.2、b=.75。", "D1中refund的tf=2且长度等于均值，贡献为ln1.6×(2×2.2)/(2+1.2)=1.375ln1.6≈0.646255；没有deadline贡献。D3长度4，分母长度项为1.2(.25+.75×4/3)=1.5，故得分.88ln1.6+(44/35)ln(8/3)≈1.646646。D2得0，排序D3、D1、D2。若人工相关集合事先标为{D1,D3}，k=1只取D3，Recall=1/2；但D3已含两个查询词，词覆盖=1。k=2时Recall才为1，仍需另查生成的每条陈述是否被原文支持。"], "formula": "BM25=Σ IDF(q)·tf(k1+1)/[tf+k1(1−b+b·dl/avgdl)]；Recall@1=.5≠词覆盖1", "bullets": ["误区：查询词出现不等于文档被人工标为相关；更不等于生成陈述受到证据支持。", "df是含词文档数，tf是单文档中出现次数，二者混用会改变稀有词权重与排名。"]}], "exercise": {"title": "从词项统计走到分层检索评价", "instructions": ["列出三份文档的长度、refund/deadline词频与文档频数。", "核对D1和D3的BM25贡献，运行k=1、2、3。", "分别记录人工相关Recall与词覆盖，解释为什么不能互相替代。", "写一条真实文档并不支持的生成结论，说明该错误属于生成忠实度而非这份排名分数。"], "deliverable": "BM25计算表、两种覆盖指标与忠实度反例"}, "quiz": [{"question": "本例D3同时含refund和deadline，k=1只取D3，人工相关集合为{D1,D3}。指标应是什么？", "options": ["Recall=1、词覆盖=.5", "Recall=.5、词覆盖=.5", "Recall=.5、词覆盖=1", "二者必然相同"], "answer": 2, "explanation": "Recall分母是两份人工相关文档，取回一份为.5；词覆盖分母是两个查询词，D3包含全部，因此为1。"}, {"question": "refund在D1出现2次、D3出现1次，总共3份文档。其BM25文档频数df是多少？", "options": ["3，因为总出现3次", "2，因为两份文档含该词", "1，因为只看当前文档", "0，因为不是唯一词"], "answer": 1, "explanation": "df数的是包含该词的文档数量，而tf数当前文档内出现次数。"}], "resources": [{"title": "官方第3讲 · PDF第40页起 retrievers：BM25、DPR 与 ColBERT", "url": "https://web.stanford.edu/class/cs329z/slides/lecture03.pdf#page=40", "type": "pdf", "local": "materials/lecture03.pdf"}, {"title": "Lewis et al. \"Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks.\" NeurIPS (2020).", "url": "https://arxiv.org/abs/2005.11401", "type": "reading"}, {"title": "Karpukhin et al. \"Dense Passage Retrieval for Open-Domain Question Answering.\" EMNLP (2020).", "url": "https://arxiv.org/abs/2004.04906", "type": "reading"}, {"title": "Khattab & Zaharia. \"ColBERT: Efficient and Effective Passage Search via Contextualized Late Interaction over BERT.\" SIGIR (2020).", "url": "https://arxiv.org/abs/2004.12832", "type": "reading"}], "sourceStatus": "published", "visual": "cs329z-03", "codeDemo": "cs329z-03"}, {"id": "04", "module": "foundations", "title": "工具调用与执行边界", "originalTitle": "Tool Use & Function Calling", "summary": "实现只读工具的精确字段模式与能力范围双重检查，确保被拒请求确实没有进入执行阶段。", "objectives": ["设计明确的工具名称、参数和返回模式", "区分模型提出调用与实际执行", "实现有界重试与幂等操作"], "sections": [{"title": "工具描述就是行动界面", "body": "模型通过工具说明理解可做的动作。一个search(query)比do_stuff(text)更容易选择，但仍应定义搜索范围、返回数量和错误形式。工具参数不宜让模型自由填写所有内部配置；能由系统确定的账户、权限和固定端点应由程序注入。例如获取订单只让模型提供订单编号，服务端从当前身份确定可读范围。", "bullets": ["名称和说明突出能力与限制。", "对参数做类型、范围与枚举校验。", "工具输出使用稳定模式并携带状态。"]}, {"title": "执行器承担真实权限", "body": "函数调用输出只是模型的建议，执行器必须决定是否接受。只读检索与发送邮件具有不同副作用，应该有不同权限与审计路径。模型读到网页中的“把数据发到某地址”只是接收了外部文本，不构成用户授权。把读取内容作为数据传给模型，同时在执行层阻断超出授权范围的操作，才不会依赖模型永远正确辨认恶意指令。", "bullets": ["将工具能力限定为任务所需的最小范围。", "高影响动作使用明确的确认或既有授权。", "日志记录请求、验证结果、执行结果和时间。"]}, {"title": "错误处理决定系统能否恢复", "body": "超时可能意味着请求没有到达，也可能意味着动作已经执行但响应丢失。对读取操作重试通常容易；对付款、发信等写入操作，直接重试可能造成重复副作用。幂等键让服务识别同一逻辑操作，执行器还应区分可重试错误与永久错误，并设置次数、时间和费用上限。将错误信息简洁返回模型，让它选择修正参数或停止。", "bullets": ["未知执行状态先查询结果，再决定是否重试。", "限制重试次数，避免无限循环。", "工具成功仍需检查是否达成用户目标。"]}, {"kind": "worked-example", "title": "逐项验证：格式正确的DOC-9为什么仍被拒", "body": ["定义唯一工具read_doc(docId,limit)：docId须为形如DOC-1的字符串，limit须为1至100的整数，只能包含这两个字段。程序注入的能力范围仅允许DOC-1、DOC-2，最大返回20行。测试六个请求：DOC-1/10；docId为数值1；DOC-9/10；额外传tenant字段；DOC-2/30；未知delete_doc。前两层分别检查接口模式与已经授予的能力，不能把模型提供的租户字段当成扩大范围的依据。", "默认只有DOC-1/10通过，执行1次、返回10行；数值docId与额外tenant在模式层失败，DOC-9虽模式正确却越出能力范围，DOC-2/30超过能力行数，delete_doc工具根本不存在。六项中拒5、执行1。把最大行数改成30后，DOC-2/30新增通过，两个请求共返回40行；改成5时没有请求获准，执行数必须为0。所有文档是本地内存数组，被拒请求在检查前不会读取任何数据；这不是付款、邮件或真实文件系统操作。"], "formula": "execute ⇔ knownTool ∧ exactSchema ∧ allowedDocId ∧ limit≤cap.maxLimit", "bullets": ["误区：符合JSON模式只表示形状合法；具体资源和数值上限仍需与当前能力比较。", "字段名、身份与授权来自不同来源。拒绝一个越权请求后，也不能先读取资源再声称未执行。"]}], "exercise": {"title": "追踪六个请求在哪一道门停止", "instructions": ["先预测每个请求的模式结果、能力结果与是否执行。", "运行maxLimit=20、30、5，核对执行数1、2、0。", "检查拒绝日志中的reason与executed=false保持一致。", "另列写操作需要的幂等与未知执行状态处理，说明为什么它们不替代本讲校验。"], "deliverable": "逐请求验证表、执行计数与扩展工具契约"}, "quiz": [{"question": "DOC-9满足docId字符串模式，但能力只允许DOC-1和DOC-2。应该怎么做？", "options": ["先读取，看内容敏感不敏感再决定", "因为JSON合法而直接执行", "让请求增加tenant字段绕过限制", "在能力检查处拒绝，且不执行读取"], "answer": 3, "explanation": "模式验证不提供资源授权，必须在执行前检查能力范围。读取后再判断已经越过边界。"}, {"question": "maxLimit=20，DOC-2请求limit=30，limit仍在模式1至100内。失败原因是什么？", "options": ["cap_limit，超过当前能力上限", "unknown_tool", "invalid_schema，因为30不是整数", "返回数据不足，因此应该静默改成20"], "answer": 0, "explanation": "模式允许1至100，但当前能力更窄。应明确拒绝超范围请求，而非不记录地改变调用含义。"}], "resources": [{"title": "官方第4讲 · PDF第48–54页接口、JSON Schema与MCP", "url": "https://web.stanford.edu/class/cs329z/slides/lecture04.pdf#page=48", "type": "pdf", "local": "materials/lecture04.pdf"}, {"title": "Schick et al. \"Toolformer: Language Models Can Teach Themselves to Use Tools.\" NeurIPS (2023).", "url": "https://arxiv.org/abs/2302.04761", "type": "reading"}, {"title": "Patil et al. \"Gorilla: Large Language Model Connected with Massive APIs.\" NeurIPS (2024).", "url": "https://arxiv.org/abs/2305.15334", "type": "reading"}, {"title": "Model Context Protocol Specification, revision 2025-06-18. modelcontextprotocol.io (2025).", "url": "https://modelcontextprotocol.io/specification/2025-06-18", "type": "reading"}], "sourceStatus": "published", "visual": "cs329z-04", "codeDemo": "cs329z-04"}, {"id": "05", "module": "foundations", "title": "框架与编排：把流程变成系统", "originalTitle": "Frameworks & Orchestration", "summary": "用实际DAG依赖和虚拟时长计算并行关键路径，观察失败重试如何推迟下游、耗尽后如何标为blocked。", "objectives": ["区分声明式模型程序与状态图编排", "说明checkpoint、trace与运行支架的作用", "用相同任务比较框架实现与直接实现"], "sections": [{"title": "声明式程序需要可评估目标", "body": "以DSPy为例，输入输出签名描述一个模块要完成的转换，模块把多个转换组合起来，优化器根据训练样例和度量寻找更好的指令或示例。这不等于无需设计：若指标奖励冗长或泄漏答案，优化器会朝错误方向前进。构建“问题→检索→带证据答案”程序时，应先明确可核验的字段和独立验证集，再讨论自动优化。", "bullets": ["签名描述输入输出，不替代业务约束。", "优化依赖数据与度量，不能凭空保证质量。", "保留未参与优化的测试任务。"]}, {"title": "状态图让分支可见", "body": "图式编排把系统拆成节点、状态与边：节点执行一步，状态承载任务信息，边决定下一步。检索不足时重新查询，验证失败时修订，预算耗尽时终止，都可以成为可见分支。checkpoint记录恢复点，适合长任务和人工介入；恢复时必须知道哪些副作用已经发生，否则重新执行节点可能重复写入。", "bullets": ["把状态字段设计成明确的数据结构。", "分支条件尽量可测试，而非全靠自然语言。", "恢复机制必须与幂等策略一起设计。"]}, {"title": "运行支架比框架名称更重要", "body": "Agent harness包括工具接口、提示模板、预算、上下文管理、执行环境和日志。这些选择会改变同一个模型的表现，所以比较系统时不能只报告模型名称。先用少量任务实现最小直接调用版本，再实现框架版本，比较开发复杂度、故障可见性与运行效果。框架的价值在于组织可靠行为，而不是多套一层抽象。", "bullets": ["每次实验记录模型、支架版本与工具版本。", "观测单个节点输入输出，也观测端到端产物。", "默认恢复与超时行为必须经过实际检查。"]}, {"kind": "worked-example", "title": "手算：一次重试为什么把13ms变成20ms", "body": ["设无副作用节点A耗3ms；A完成后B耗5ms、C耗2ms，可并行；D耗4ms但必须等B与C成功；E耗1ms依赖D。假设执行槽位足够且没有调度开销。无失败时A在0–3，B在3–8，C在3–5，D在8–12，E在12–13，总时间13ms，关键路径A→B→D→E。把全部时长直接相加得到15ms，会忽略B与C的并行。", "现在B第一次失败，最多允许一次重试，等待2ms后重试。B第一轮3–8失败，8–10等待，第二轮10–15成功；独立C仍在3–5完成，D延至15–19，E延至19–20，总时间20ms。已执行节点及退避若全顺序排列，工作量为22ms。若B连续失败两次，15ms后重试预算耗尽，D与E因依赖失败被标为blocked、执行次数0；运行在15ms结束但任务不成功。该时间表是社区内存模型，不是LangGraph或远端工具的实测结果。"], "formula": "start(v)=max finish(dependencies)；无失败关键路径3+5+4+1=13；一次重试后3+5+2+5+4+1=20", "bullets": ["误区：运行结束不等于全部节点成功；blocked节点没有产物，不能作为成功输入向下游传播。", "有限重试与副作用幂等属于不同问题。本例节点无副作用，真实写操作恢复还需动作一致性。"]}], "exercise": {"title": "为并行节点与失败依赖画甘特图", "instructions": ["手算无失败时各节点start/end与13ms关键路径。", "模拟B一次失败，确认2ms退避与第二次尝试时段。", "模拟B两次失败，检查D/E的blocked与0次尝试。", "为真实编排实现另列队列争用、检查点和外部副作用会增加的状态。"], "deliverable": "三种失败次数的时间表、关键路径与状态转移说明"}, "quiz": [{"question": "A3后B5与C2并行，随后D4等待两者，最后E1。无失败且槽位足够，总时间是多少？", "options": ["15ms", "11ms", "13ms", "8ms"], "answer": 2, "explanation": "关键路径A→B→D→E为3+5+4+1=13；C在B完成前结束，不额外增加2ms。"}, {"question": "B最多重试一次且两次都失败，D依赖B与C、E依赖D。D/E应该是什么状态？", "options": ["success，因为流程已结束", "blocked，不能消费缺失的成功产物", "各自盲目重试直到成功", "跳过B输入也自动算成功"], "answer": 1, "explanation": "依赖失败后，D/E不满足启动前置条件。本例记录blocked且attempts=0，避免将未执行误算成功。"}], "resources": [{"title": "官方第5讲 · PDF第53–58页 LangGraph状态、节点与边", "url": "https://web.stanford.edu/class/cs329z/slides/lecture05.pdf#page=53", "type": "pdf", "local": "materials/lecture05.pdf"}, {"title": "Khattab et al. \"DSPy: Compiling Declarative Language Model Calls into Self-Improving Pipelines.\" ICLR (2024).", "url": "https://arxiv.org/abs/2310.03714", "type": "reading"}, {"title": "LangChain. \"LangGraph Overview.\" LangChain Docs.", "url": "https://docs.langchain.com/oss/python/langgraph/overview", "type": "reading"}, {"title": "Arena.ai. \"HarnessTax: How Much Does the Harness Matter for Coding Agents?\" Arena Blog (2026).", "url": "https://arena.ai/blog/coding-agents-harness-tax", "type": "reading"}, {"title": "官方第5讲示范代码", "url": "https://github.com/cs329z/lecture5-frameworks", "type": "code", "local": "materials/lecture5-frameworks.zip"}], "sourceStatus": "published", "visual": "cs329z-05", "codeDemo": "cs329z-05"}, {"id": "06", "module": "agent-design", "title": "设计智能体：工作流、行动循环与上下文", "originalTitle": "Agent Design Patterns & Scaffolds", "summary": "用显式的条件质量、弃答收益和核验成本比较下一步动作，区分“能继续调用”与“值得继续调用”。", "objectives": ["根据任务路径是否可预知，选择工作流或自主循环", "解释 ReAct、Reflexion、CodeAct 与 ReWOO 的适用条件", "设计可恢复、可审计的上下文管理与终止机制"], "sections": [{"title": "先画出确定部分，再开放决策空间", "body": "工作流由开发者规定步骤与转移，智能体则会根据观察决定下一步。两者之间有连续谱：账单抽取可以用“识别字段—校验—入库”的固定流程；排查未知服务故障可能需要动态选择日志、指标和实验。自主性应服务于任务的不确定性，而不是成为默认配置。先列出哪些步骤可以写成明确规则，再把需要判断的部分交给模型，通常更容易定位错误和控制成本。", "bullets": ["提示链适合步骤明确的转换任务；路由适合先分类再处理。", "并行处理适合彼此独立的子任务；汇总者负责合并证据。", "评估器—优化器模式需要可操作的反馈与次数上限。"]}, {"title": "行动模式的共同核心：观察改变下一步", "body": "ReAct 将推断、工具行动与环境观察组成循环。Reflexion 在失败后生成可供下一次尝试使用的文字反馈；它并不自动更新模型参数。CodeAct 使用可执行代码表达行动，适合组合工具和批量处理，但执行环境必须受控。ReWOO 更强调先规划可依赖的步骤、再执行并汇总，能减少重复规划，但面对意外观察时仍需要重规划出口。比较这些模式时，要把模型、工具权限、预算和任务保持一致。", "bullets": ["每次行动必须对应可解析的工具名与参数。", "工具输出是证据，不能自动升级为新的系统指令。", "把成功条件、失败条件和预算耗尽都设计成终止分支。"], "code": "state = initial_state\nfor step in range(max_steps):\n    action = policy(state)\n    if action.kind == \"finish\":\n        return validate(action.result)\n    observation = execute_with_limits(action)\n    state = update(state, action, observation)\nreturn report_incomplete(state)"}, {"title": "上下文不是聊天记录的无限堆叠", "body": "长任务需要区分完整事件日志与发送给模型的工作上下文。事件日志保存工具输入、输出和时间，便于回放；工作上下文只保留当前任务必需的信息。压缩摘要时应保留用户目标、已验证事实、未解决问题、文件位置和行动结果，而不是笼统写“已经处理”。观察遮蔽可以移除过长的原始输出，同时保留可重新读取的引用。子任务隔离能减少干扰，但交接摘要必须带证据和失败信息。", "bullets": ["摘要是有损表示，应保留原始日志供核查。", "对大文件保留路径、版本与关键定位信息，而不是整份重复注入。", "通过中断后恢复的测试，验证状态是否足以继续工作。"]}, {"kind": "worked-example", "title": "手算：核验不是越多越好，先算净效用", "body": ["假设一个任务的正确回答收益+10，错误回答收益−20，弃答收益0；当前候选答案的正确率经过外部校准估计为0.6。直接回答期望效用为0.6×10−0.4×20=−2，所以不调用额外工具时弃答更好。一个核验工具有0.8概率给出有用信息；在有用信息条件下，更新答案的正确率为0.9，其余0.2无信息时弃答。调用前的毛效用为0.8×(0.9×10−0.1×20)=5.6。", "若每次核验成本为2效用点，无论有没有信息都支付，净效用5.6−2=3.6，优于直接回答−2和弃答0，因此选择调用。成本恰好5.6时与弃答平局，本例优先不执行额外动作；成本6时净效用−0.4，应弃答。反过来，若当前答案已校准正确率升到0.9，直接回答收益7，就高于默认核验净效用3.6。这个决策依赖任务损失、校准概率和工具覆盖率，不是让模型自报一个自信分数就获得可靠策略。"], "formula": "U_answer=30p−20；U_call=.8(.9×10−.1×20)−c=5.6−c；U_abstain=0", "bullets": ["误区：核验可用率0.8与可用时正确率0.9分别是覆盖率和条件准确率；无信息分支会弃答，不能把乘积直接冒充整体回答准确率。", "成本必须与任务收益在同一效用单位；若要纳入钱、时延或人工负担，先声明转换规则和估计误差。"]}], "exercise": {"title": "给一次工具调用写决策依据", "instructions": ["手算当前直接回答、核验毛收益与默认净收益。", "运行cost=2、5.6、6，检查调用、平票弃答、负收益弃答。", "把currentAccuracy改成.9，解释为什么此时直接回答胜出。", "为真实任务说明怎样估计工具可用率、校准质量与错误代价，而不是直接使用模型自信。"], "deliverable": "动作效用表、明确平票规则与参数估计方案"}, "quiz": [{"question": "核验有用概率.8，有用时正确率.9，正确+10、错误−20，无信息弃答0；调用成本2。净效用是多少？", "options": ["3.6", "5.6", "7", "−2"], "answer": 0, "explanation": "毛效用.8×(.9×10−.1×20)=5.6，再减每次调用成本2，得到3.6。"}, {"question": "当前直接回答效用−2，弃答0，核验毛效用5.6、成本6。按本例策略应做什么？", "options": ["调用，因为工具次数还有剩余", "弃答，因为0高于核验−.4与直接回答−2", "直接回答，因为已经有候选文本", "无限重试直到出现正收益"], "answer": 1, "explanation": "预算允许与预期收益值得是两个条件；这里核验净效用为−.4，弃答是三者中最高的0。"}], "resources": [{"title": "官方第6讲 · PDF第33页起 ReAct与行动模式；效用计算为社区补充", "url": "https://web.stanford.edu/class/cs329z/slides/lecture06.pdf#page=33", "type": "pdf", "local": "materials/lecture06.pdf"}, {"title": "Yao et al. \"ReAct: Synergizing Reasoning and Acting in Language Models.\" ICLR (2023).", "url": "https://arxiv.org/abs/2210.03629", "type": "reading"}, {"title": "Schluntz & Zhang. \"Building Effective AI Agents.\" Anthropic (2024).", "url": "https://www.anthropic.com/engineering/building-effective-agents", "type": "reading"}, {"title": "LangChain. \"Context Engineering.\" LangChain Blog (2025).", "url": "https://www.langchain.com/blog/context-engineering-for-agents", "type": "reading"}, {"title": "Shinn et al. \"Reflexion: Language Agents with Verbal Reinforcement Learning.\" NeurIPS (2023).", "url": "https://arxiv.org/abs/2303.11366", "type": "reading"}, {"title": "Wang et al. \"Executable Code Actions Elicit Better LLM Agents.\" ICML (2024).", "url": "https://arxiv.org/abs/2402.01030", "type": "reading"}], "sourceStatus": "published", "visual": "cs329z-06", "codeDemo": "cs329z-06"}, {"id": "07", "module": "agent-design", "title": "记忆架构：让经验可检索、可更新、可遗忘", "originalTitle": "Agent Memory Architectures", "summary": "先处理权限、撤回、过期与事实版本，再用显式时间评分排序；让“时间很新”与“事实仍有效”分开接受检查。", "objectives": ["区分工作、情景、语义与程序性记忆", "解释分层存储、检索和记忆整合的作用", "为记忆设置更新、过期、删除与权限规则"], "sections": [{"title": "四类记忆解决四种不同问题", "body": ["工作记忆保存当前任务目标与正在使用的信息；情景记忆记录发生过的具体事件，例如一次失败部署；语义记忆保存可复用的事实，例如项目使用的数据库版本；程序性记忆保存完成任务的步骤，例如发布前的验证流程。一个事件可能生成多种记忆，但不能直接把“某次成功”当成永远正确的规则。记忆条目至少应包含内容、来源、时间与适用范围，才能在检索之后判断是否仍然可信。"], "bullets": ["情景：昨天在测试环境升级依赖后出现兼容性错误。", "语义：当前生产服务依赖某个已验证版本。", "程序：升级前运行兼容性检查并保留回滚点。"]}, {"title": "分层记忆需要明确的读写策略", "body": ["借鉴 MemGPT 类架构，可以把少量高价值状态放在上下文，将较大的历史放到外部存储，按需检索回来。系统真正困难的地方不是“使用向量数据库”，而是决定何时写入、检索什么以及何时更新。检索应同时考虑相关性、时间与权限；写入应经过必要性检查，避免把一次猜测永久保存为事实。反思式整合可以将多次事件提炼成规律，但产生的新条目仍应标记为推断，并保留支持它的事件引用。", "排序只是最后一步。访问范围、删除状态、到期时间与明确版本替代关系应先作为资格约束处理；否则一个相似度很高的过时缓存可能压过已经确认的新事实。更新时间还要区分原事实验证时间和重新索引时间，重新写入向量库不等于事实重新获得验证。"], "bullets": ["先按用户或项目隔离候选集合，再进行语义检索。", "设置检索阈值与数量上限，防止无关记忆淹没当前任务。", "维护可修订的事实记录，保留旧值和变更来源。"], "code": "memory = {\n  \"kind\": \"semantic\",\n  \"scope\": \"project-a\",\n  \"claim\": \"Deployment uses a staging gate\",\n  \"source\": \"approved-release-config\",\n  \"verified_at\": \"2026-11-06\",\n  \"expires_at\": None,\n  \"status\": \"verified\"\n}"}, {"title": "遗忘也是正确性的组成部分", "body": ["持久记忆会让错误跨会话传播，也可能保存已经撤回的偏好和敏感信息。应为条目设定过期策略、删除入口、访问范围与冲突解决规则。用户曾经偏好详细回答，不代表每次都必须详细；当前明确指令应优先于历史推断。评估记忆系统时，不只测试“能否记住”，还要测试“应否调用”与“能否忘记”：注入一个过时事实、修改用户偏好，再观察系统是否仍然坚持旧结论。"], "bullets": ["对临时状态使用较短生命周期，对关键事实要求重新验证。", "删除主记录时检查摘要、缓存与派生条目是否仍保留同一信息。", "记录错误检索率与过时信息使用率，避免只优化命中率。"]}, {"kind": "worked-example", "title": "手算：旧事实今天被重新索引，也不应胜过新版本", "body": ["构造六条合成记忆：region旧缓存v1相关性.99、今天重索引；region当前事实v2相关性.8、2天前验证；build近期流程相关性.7、今天验证；另有20天前且TTL7天的依赖记录、scope B的其他项目记录、status deleted的已撤回偏好。先按项目、删除与TTL过滤掉后三条，再按region的已验证版本淘汰v1，只剩current与recent。旧缓存虽然时间最新，也不能因为排序分数高就覆盖v2。", "社区演示采用score=relevance×2^(−ageDays/halfLifeDays)。半衰期2天时，current=.8×2^(−2/2)=.4，recent=.7×1=.7，因此recent排第一。半衰期14天时current≈.72458，超过recent的.7，排序交换，但region有效版本始终v2。这个公式是本例可解释的检索策略，不是MemGPT/Mem0统一规定，更不是真实性概率。删除和越权记录不会因为半衰期变长而重新变合法。"], "formula": "硬过滤→同key版本选择→score=relevance·2^(−ageDays/halfLifeDays)；h=2时current=.4、recent=.7", "bullets": ["误区：今天重索引不等于今天验证了事实；时间字段必须说明含义。", "硬过滤不能替代完整生命周期治理；删除主记录时还需处理派生摘要、缓存和备份中的相关副本。"]}], "exercise": {"title": "让记忆测试覆盖“不能返回”的记录", "instructions": ["运行半衰期2和14天，记录合法候选、排序与事实版本。", "将越权、删除、过期候选的相关性改高，确认它们仍被过滤。", "为真实设计区分事实验证时间、事件时间和索引时间，并定义冲突处理。", "写出删除请求需要检查的主记录、摘要、缓存与派生记忆路径。"], "deliverable": "候选过滤轨迹、时间字段定义与删除传播检查表"}, "quiz": [{"question": "当前事实相关性.8、年龄2天、半衰期2天，score=.8×2^(−2/2)，得分是多少？", "options": [".8", ".2", ".4", "1.6"], "answer": 2, "explanation": "经过一个半衰期，得分减半，为.4。它是排序分数，不是该事实真实的概率。"}, {"question": "同一事实v1今天重新索引、v2两天前已验证为新版本，合理处理是什么？", "options": ["只按索引时间选v1", "把两个冲突值都当作当前事实", "先按版本替代关系保留v2，再在合法候选内排序", "提高v1向量相似度直到获胜"], "answer": 2, "explanation": "重新索引不会更新事实版本。明确的版本替代关系是资格约束，不应被软排序分数覆盖。"}], "resources": [{"title": "官方课件 · 记忆维护PDF第61–64页；遗忘边界第96–100页", "url": "https://web.stanford.edu/class/cs329z/slides/lecture07.pdf#page=61", "type": "pdf", "local": "materials/lecture07.pdf"}, {"title": "Sumers et al. \"Cognitive Architectures for Language Agents.\" TMLR (2024).", "url": "https://arxiv.org/abs/2309.02427", "type": "reading"}, {"title": "Packer et al. \"MemGPT: Towards LLMs as Operating Systems.\" arXiv (2023).", "url": "https://arxiv.org/abs/2310.08560", "type": "reading"}, {"title": "Park et al. \"Generative Agents: Interactive Simulacra of Human Behavior.\" UIST (2023).", "url": "https://arxiv.org/abs/2304.03442", "type": "reading"}], "sourceStatus": "published", "visual": "cs329z-07", "codeDemo": "cs329z-07"}, {"id": "08", "module": "agent-design", "title": "多智能体协作：分工、交接与一致性", "originalTitle": "Multi-Agent Systems", "summary": "用共同基线上的字段补丁区分无修改、同值修改与真实冲突，保留暂存与已提交状态，避免并行角色静默覆盖彼此。", "objectives": ["判断单智能体与多智能体的适用边界", "比较协调者、群体协作与混合结构", "设计任务账本、交接格式和共享资源隔离"], "sections": [{"title": "更多智能体不等于更可靠", "body": ["多智能体最直接的价值是并行处理独立工作，或隔离不同任务的上下文。例如资料收集、代码实现和文案核查可以部分并行；一个依赖前一步结果的串行推导则未必受益。每增加一个角色，都会产生任务描述、结果传递、冲突处理和验证成本。先建立单智能体基线，再衡量多智能体是否在相同预算下提高成功率或缩短耗时。若所有角色使用相似模型和资料，它们也可能共享同一种错误。"], "bullets": ["把任务画成依赖图，优先并行无相互写入的分支。", "不应把重复意见数量当成独立证据强度。", "记录协调成本，包括重复工作、无效等待和合并失败。"]}, {"title": "协作拓扑必须对应任务结构", "body": ["协调者结构由一个主智能体拆分任务、分配资源并合并结果，适合最终交付物明确的工作。群体结构允许角色之间直接交接，适合需要在不同专长间切换的流程，但更难追踪责任。混合结构可以在局部任务内灵活协作，同时由主流程维护全局状态。无论使用消息传递、共享看板还是 A2A 类协议，都需要定义完成标准与输出契约；协议使消息可交换，却不会自动保证事实正确或目标一致。"], "bullets": ["任务契约包含目标、可写范围、输入、输出格式和验收条件。", "交接包含已完成内容、证据、未决问题与下一步，而不只是结论。", "协调者负责核验关键结果，不把子智能体“成功”标签当成证据。"], "code": "task = {\n  \"id\": \"verify-resources\",\n  \"depends_on\": [\"collect-links\"],\n  \"owner\": \"checker\",\n  \"write_scope\": [\"reports/resource-check.json\"],\n  \"acceptance\": \"Every URL has status and checked_at\",\n  \"status\": \"in_progress\"\n}"}, {"title": "共享状态需要所有权与提交边界", "body": ["两个智能体同时修改同一文件，可能覆盖彼此的改动；两个智能体重复执行外部操作，可能产生重复记录。对代码任务可以使用独立工作目录或 worktree，再由负责人合并；对数据任务可以划分记录范围并使用幂等键。任务账本应保存待办、进行中、完成与失败状态，以及当前负责人。超时不能自动被视为完成，重试之前需要检查原操作是否已经产生结果。用可恢复的状态机比依靠自然语言约定更可靠。", "合并时应保存共同基线：某个角色保留基线值并不等于提出反对修改；两个角色对同字段给出相同新值也不构成文本冲突。真正需要阻断的是同一基线上的多个不同新值。候选合并状态与已发布状态必须分离，不能把未解决冲突的部分结果宣称为整体完成。"], "bullets": ["优先按文件、模块或数据分区分配写入所有权。", "外部副作用应集中执行，或使用可验证的幂等机制。", "通过故意制造延迟、重复消息和部分失败来测试协调逻辑。"]}, {"kind": "worked-example", "title": "手算：三个补丁，为什么retries暂存为3却尚未提交", "body": ["共同基线为timeout=30、retries=2。Agent A提议timeout=60，B提议retries=3，C提议timeout=45。相对基线收集变化后，retries只有一个目标值3，可暂存；timeout有60和45两个不同目标值，需要人工或协调者依据证据解决。候选合并保持timeout=30、retries=3，但整个提交被阻止，所以已提交状态仍是30、2。暂存与生效不是同一件事。", "把C的提议改为30，它只是没有修改timeout，不构成对A的否决，因此可以合并为60、3。把C改为60，两个角色同值修改也可合并为60、3。两个角色一致仍不保证这个超时值适合产品；字段冲突检测只防止静默覆盖，最终还需要契约验证、测试和基线版本检查。本例只操作内存对象，不启动真实智能体、不写配置。"], "formula": "Δagent={field:value | value≠base[field]}；同字段多个不同新值→冲突；有冲突→保持原提交状态", "bullets": ["误区：“最后返回的角色覆盖先返回角色”不是可靠的协调规则。", "一个无文本冲突的合并仍可能有跨字段语义冲突；测试不能因投票一致而省略。"]}], "exercise": {"title": "为并行任务定义可审核的合并边界", "instructions": ["运行C=30、45、60，分别解释无修改、冲突和同值修改。", "记录暂存对象、冲突字段和最终提交对象，拒绝静默覆盖。", "给三个角色分配文件所有权、共同基线与验收规则，再模拟基线已被别人更新。", "构造一个字段上无冲突但语义上错误的组合，说明需要什么测试。"], "deliverable": "任务契约、三方补丁记录与冲突/语义验收报告"}, "quiz": [{"question": "基线30/2，A改timeout60、B改retries3、C改timeout45，整份原子提交需无冲突。暂存与已提交结果分别是什么？", "options": ["60/3与60/3", "45/3与45/3", "30/2与30/3", "30/3与30/2"], "answer": 3, "explanation": "timeout冲突保持基线30，retries可暂存为3；但整份提交被阻止，已提交对象仍为30/2。"}, {"question": "C提议timeout=30，与共同基线相同，A提议60。三方合并应如何解释C？", "options": ["C以否决票阻止A", "C没有改变该字段，可接受A的唯一变化", "30与60必然形成修改冲突", "必须取二者平均45"], "answer": 1, "explanation": "变化应相对共同基线计算。保留基线不等于提出另一个修改；A是该字段唯一有效变化。"}], "resources": [{"title": "官方课件 · 任务账本PDF第52–56页；隔离第62–63页", "url": "https://web.stanford.edu/class/cs329z/slides/lecture08.pdf#page=52", "type": "pdf", "local": "materials/lecture08.pdf"}, {"title": "Wu et al. \"AutoGen: Enabling Next-Gen LLM Applications via Multi-Agent Conversation.\" COLM (2024).", "url": "https://arxiv.org/abs/2308.08155", "type": "reading"}, {"title": "Cemri et al. \"Why Do Multi-Agent LLM Systems Fail?\" NeurIPS Datasets & Benchmarks (2025).", "url": "https://arxiv.org/abs/2503.13657", "type": "reading"}, {"title": "Kim et al. \"Towards a Science of Scaling Agent Systems.\" arXiv (2025).", "url": "https://arxiv.org/abs/2512.08296", "type": "reading"}], "sourceStatus": "published", "visual": "cs329z-08", "codeDemo": "cs329z-08"}, {"id": "09", "module": "agent-design", "title": "优化智能体：从提示和示例到模型权重", "originalTitle": "Optimization", "summary": "用逐轮淘汰与增量记账分配提示搜索预算，观察小样本淘汰风险，并把选择结果与独立测试严格分开。", "objectives": ["区分上下文优化、系统优化与权重优化", "解释提示搜索、示例选择、SFT 和 RL 的反馈差异", "使用训练/开发/测试划分避免评估泄漏"], "sections": [{"title": "优化开始于可复现的基线", "body": ["先固定任务集、模型版本、工具、预算和评分方式，保存失败轨迹，再决定优化目标。若失败来自检索不到正确文档，改写最终回答提示可能收效有限；若工具参数经常非法，应该检查接口、示例与校验。成功率也不是唯一目标：可以在质量达标的前提下降低延迟与调用成本。把问题定位到数据、上下文、工具或模型能力后，优化才有可解释的方向。"], "bullets": ["训练集用于学习，开发集用于选择方案，测试集用于最终报告。", "在最终测试集上反复挑选提示，会把测试集变成开发集。", "同时记录任务成功、预算耗尽、工具错误、成本与尾部延迟。"], "formula": "目标示例：在 success_rate ≥ τ 的约束下，最小化 mean_cost；τ 由产品需求定义。"}, {"title": "上下文优化是在搜索可执行的配置", "body": ["提示词、演示样例、检索参数和模块组合都可以成为搜索空间。MIPROv2 类方法联合探索指令与示例；OPRO 用语言模型提出候选；TextGrad 使用文字反馈指导修改；GEPA 类方法利用执行反馈反思并演化候选。它们的共同点是“生成候选—在任务上评估—根据反馈更新”，并非单纯让模型把提示写得更长。小型开发集上很容易过拟合，因此应检查不同任务类型的表现，并记录搜索使用了多少次评估。", "预算可以分阶段分配：先给全部候选较小资源，只让部分候选获得更大预算。下方successive halving是社区调度算例，并非声称GEPA或MIPRO必须使用这段实现。它节省的是开发评估次数，同时引入早期误淘汰风险，不能把预算效率直接称为最优候选保证。"], "bullets": ["先优化一个有证据的问题，避免同时改变多个组件导致无法归因。", "演示样例应覆盖关键边界，不能混入测试题答案。", "保存候选配置与评估轨迹，允许回滚并复现实验。"]}, {"title": "权重优化需要适合的信号与治理", "body": ["SFT 从示范轨迹学习行为，数据质量取决于轨迹是否正确、完整且适合部署环境。强化学习则用奖励信号调整策略；PPO 和 GRPO 是不同的策略优化方法，但奖励设计错误都可能诱导投机行为。只奖励最终答案可能掩盖高成本或不合规工具使用，因此需要同时检查执行过程。提示优化通常迭代快、部署简单；权重优化适合规模化且稳定的行为需求，却引入训练、版本、回归和数据维护成本。二者可以结合，不能仅凭方法新颖程度选择。"], "bullets": ["把正确答案、有效行动与无效重试分开标注。", "验证奖励是否可被“看似成功”的轨迹欺骗。", "在未参与训练的任务上检验泛化，并保留旧模型作为回归基线。"]}, {"kind": "worked-example", "title": "手算：四个候选如何只花16次评估选出一个", "body": ["固定四个候选A/B/C/D和同一开发任务顺序，预算层级为每项2、4、8题。第一轮2题结果分别为2、1、1、0分，保留A与B；B/C同分按预先规定的ID顺序处理。第二轮只给幸存者追加到4题，A为2/4，B为3/4，保留B。第三轮将B追加到8题，最终6/8=.75。所有结果为合成fixture，不涉及真实模型调用。", "第一轮花4×2=8次，第二轮只追加2×(4−2)=4次，第三轮追加1×(8−4)=4次，共16次；若四个候选全部评8题则要32次。第一轮资源改为1题时最终可能选A；改为4题时会让C进入后轮并最终胜出，展示小样本与淘汰规则的敏感性。6/8参与了配置选择，仍是开发结果，不能包装成独立泛化分数；冻结候选后应另用此前未查看的测试任务。"], "formula": "资源n→2n→4n，候选4→2→1；复用结果时成本4n+2n+2n=8n；n=2时16次", "bullets": ["误区：每一轮重新评完整前缀会多花预算；是否复用必须与实验确定性和缓存策略一致。", "早期淘汰节省评估，但可能丢掉最终更强候选；试验次数与选择过程都应记录，不能只留下胜者分数。"]}], "exercise": {"title": "给提示搜索建立不可混淆的账本", "instructions": ["按2→4→8手算每轮保留者、增量任务数与总预算。", "将初始预算改为1或4，比较候选选择是否稳定。", "固定候选ID同分规则、任务顺序和结果复用条件。", "将最终测试字段与开发分数字段分开保存，配置冻结后再报告独立结果。"], "deliverable": "逐轮候选账本、增量预算表与冻结后的测试协议"}, "quiz": [{"question": "四候选2题选二、两候选追加至4题选一、一候选追加至8题，已有结果复用，总评估次数是多少？", "options": ["32", "24", "16", "8"], "answer": 2, "explanation": "成本4×2+2×(4−2)+1×(8−4)=8+4+4=16。每轮已完成前缀不重复计入。"}, {"question": "用开发任务逐轮选出B并获得6/8后，最稳妥的下一步是什么？", "options": ["冻结配置，再使用此前未参与选择的测试任务", "把6/8称为独立测试成绩", "继续修改B直到在这8题全对，再称测试", "删除所有被淘汰候选的记录"], "answer": 0, "explanation": "6/8属于参与选择的开发结果，不能提供独立泛化测量。冻结后使用独立测试，并保留搜索成本与失败记录。"}], "resources": [{"title": "官方课件 · 优化方法总结PDF第65–69页", "url": "https://web.stanford.edu/class/cs329z/slides/lecture09.pdf#page=65", "type": "pdf", "local": "materials/lecture09.pdf"}, {"title": "Agrawal et al. \"GEPA: Reflective Prompt Evolution Can Outperform Reinforcement Learning.\" ICLR (2026).", "url": "https://arxiv.org/abs/2507.19457", "type": "reading"}, {"title": "Opsahl-Ong et al. \"Optimizing Instructions and Demonstrations for Multi-Stage Language Model Programs.\" EMNLP (2024).", "url": "https://arxiv.org/abs/2406.11695", "type": "reading"}, {"title": "Shao et al. \"DeepSeekMath: Pushing the Limits of Mathematical Reasoning in Open Language Models.\" arXiv (2024).", "url": "https://arxiv.org/abs/2402.03300", "type": "reading"}], "sourceStatus": "published", "visual": "cs329z-09", "codeDemo": "cs329z-09"}, {"id": "10", "module": "data-evaluation", "title": "Terminal-Bench：评估真实终端任务", "originalTitle": "📺 Guest Lecture: Terminal-Bench", "summary": "用四类虚拟产物测试验收器：正常退出、文件存在、结构合法都不等于语义正确，最终成功需要全部契约断言。", "objectives": ["区分终端任务的说明、环境、智能体和评分器", "设计能够识别真实完成状态的验证方法", "解释环境差异、随机性与污染如何影响分数"], "sections": [{"title": "一个终端任务是一份可执行契约", "body": ["终端智能体可能需要安装依赖、修复代码、处理数据或配置服务。任务说明应明确目标和交付物，环境则提供起始文件、工具与约束。评分器需要判断最终状态是否满足要求，而不是只检查智能体是否输出“完成”。例如数据清洗任务应核验文件内容、行数与格式约束；服务修复任务应执行外部可观察的健康检查。任务越接近真实工作，越需要把偶然的环境故障和真正的能力不足分开记录。"], "bullets": ["请求描述目标，环境定义可行动空间，评分器验证结果。", "隐藏评估细节可以降低针对固定断言投机的风险。", "任务本身也要验证：起始状态可复现，正确解法确实能通过。"]}, {"title": "运行框架决定智能体实际面对什么", "body": ["同一个模型配上不同工具接口、超时和上下文策略，可能得到不同结果。终端运行框架需要管理进程生命周期、工作目录、命令输出截断、文件访问和资源限制。一个长时间运行的命令如果被误判为失败，智能体可能重复启动进程；输出被截断又没有文件引用，诊断信息可能丢失。因此报告分数时应描述模型之外的运行条件，并保存可回放的命令与观察轨迹。基准比较的是整个系统在给定条件下的行为。"], "bullets": ["记录模型版本、工具配置、超时、预算与运行框架版本。", "每次评估从干净环境开始，避免前次执行留下的文件影响结果。", "将超时、基础设施错误与任务失败分别统计。"]}, {"title": "评分器也需要反例测试", "body": ["测试通过并不天然等于任务完成。若评分器只检查文件存在，智能体创建一个空文件就可能得分；若只检查固定样例，硬编码答案可能通过。评分器应覆盖任务的核心语义，并用故意错误的产物进行反例测试。另一方面，过于严格的输出字符串比较会误杀有效方案。应在可接受解的集合上评分，保留足够的运行记录解释失败。重复运行还能揭示随机性：一次偶然成功与稳定交付是不同能力。", "退出码0只能说明进程按自己的协议正常结束；程序可能正常地输出空文件或错误结果。可解析、字段类型、唯一性和任务语义应分别形成可定位的断言，再使用逻辑与决定整体完成。本页实验中的report.json只是在内存中保存的字符串，不是实际Terminal-Bench任务运行。"], "bullets": ["测试空产物、硬编码答案、部分完成与格式正确但内容错误等情况。", "用独立于智能体的验证器检查最终状态。", "报告运行次数与任务级结果，不只公布一个总平均分。"], "code": "def score(result_path):\n    rows = read_csv(result_path)\n    assert required_columns <= set(rows.columns)\n    assert rows[\"id\"].is_unique\n    assert rows[\"amount\"].notna().all()\n    assert matches_expected_transform(rows)\n    return True"}, {"kind": "worked-example", "title": "手算：五项检查通过，任务仍然失败", "body": ["任务输入是三条合成记录(a,\"2\")、(b,\"3\")、(b,\"3\")，要求按id去重并将金额数值化，输出a=2、b=3及total=5。验证器检查6项：退出码0、report.json存在、JSON可解析、字段与数值类型有效、id唯一、最终转换语义正确。四种虚拟产物都设退出码0，但分别是缺失、空字符串、结构合法却写成a=2/b=30/total=32、完全正确。", "缺失产物只通过退出码，计1/6；空字符串通过退出码与存在，计2/6；内容错误JSON前五项全过，却未满足转换语义，计5/6且整体失败；正确产物6/6才成功。总分5/6不能被解释成任务已大致完成，因为关键语义是必需条件。这个纯内存模拟用来审查评分器反例，没有调用shell、容器、真实文件系统或官方Terminal-Bench，也没有产生任何基准成绩。"], "formula": "success=exitOK∧exists∧parseable∧schema∧uniqueIDs∧semanticMatch；四种反例通过数=[1,2,5,6]", "bullets": ["误区：让被评智能体自己声称success，或只看进程退出，都无法独立验证最终状态。", "真实任务还需检查环境版本、隔离、预算、可接受解集合与基础设施故障；本例只隔离产物验收机制。"]}], "exercise": {"title": "先攻击验收器，再使用验收器评系统", "instructions": ["运行缺失、空、内容错、正确四种产物，逐项核对断言。", "再添加重复id、金额字符串和硬编码错误总和反例。", "说明哪些不同但语义等价的正确输出应被允许，避免死板字符串比较。", "设计真实终端评估时另列环境、隔离、预算与失败分类，勿把本页模拟计为真实benchmark。"], "deliverable": "六项断言矩阵、反例产物与真实评估协议清单"}, "quiz": [{"question": "虚拟产物JSON合法、字段正确、id唯一，但把b金额3写成30，退出码0。六项检查结果最合理的是？", "options": ["6/6且成功", "只要退出码0就成功", "0/6，因为所有形式检查都作废", "5/6且整体失败"], "answer": 3, "explanation": "前五个形式条件仍成立，但必需的语义条件失败。整体使用逻辑与，不能用通过比例替代完成判定。"}, {"question": "report.json存在但内容为空字符串，进程退出码0，本讲六项检查中通过几项？", "options": ["1项", "2项", "5项", "6项"], "answer": 1, "explanation": "只有正常退出与文件存在成立；空字符串不是可解析JSON，后续结构、唯一性与语义检查也不成立。"}], "resources": [{"title": "官方课件 · 任务与框架PDF第42–44页；验证器第49页", "url": "https://web.stanford.edu/class/cs329z/slides/lecture10.pdf#page=42", "type": "pdf", "local": "materials/lecture10.pdf"}, {"title": "Terminal-Bench 官方项目", "url": "https://www.tbench.ai/", "type": "website"}, {"title": "Merrill et al. \"Terminal-Bench: Benchmarking Agents on Hard, Realistic Tasks in Command Line Interfaces.\" ICLR (2026).", "url": "https://arxiv.org/abs/2601.11868", "type": "reading"}], "sourceStatus": "published", "visual": "cs329z-10", "codeDemo": "cs329z-10"}, {"id": "11", "module": "data-evaluation", "title": "智能体的数据：从轨迹到改进", "originalTitle": "What Data Do Agents Need?", "summary": "用canonical task ID把多次运行归回原任务，比较轨迹平均与任务均匀平均，避免复制易题成功轨迹制造虚假提升。", "objectives": ["区分示范、运行轨迹与反馈标签", "避免训练数据污染评测", "设计最小而充分的运行记录"], "sections": [{"title": "一条轨迹不仅是聊天记录", "body": ["智能体轨迹应包含任务、初始环境、每一步观察、工具请求、执行结果和最终产物。只保留最终回答会丢掉错误来源：一个答案可能正确，但经历了未经授权的查询；也可能结论错误，却是检索返回旧版本造成。为每个事件加入时间、工具版本与关联ID，就能重建决策所见的证据，而不需要保存无关的个人信息。", "最终成功标签也不能自动赋给所有前缀动作：某一步可能无效、冗余或引入风险，系统后来靠恢复步骤才成功。步骤评价需要结合当时可见观察、合法动作与后续结果，不能仅依据最终答案倒推每一步都正确。"], "bullets": ["任务级成功标签解释结果，步骤级标签解释过程。", "错误、重试和被拒绝动作同样有诊断价值。", "日志采集应最小化敏感内容并设置保留期限。"]}, {"title": "为不同用途保留不同数据", "body": ["示范数据教系统怎样做，反馈数据告诉系统哪些行为较好，评测数据衡量改进是否泛化。把同一个任务的改写分到训练和测试两边，会让系统通过记忆主题取得虚高分数。应按任务来源、用户或时间切分，并保留从未参与提示设计、权重训练或人工调参的测试集。训练成功轨迹可以教格式，失败轨迹更适合揭示恢复策略和边界。", "采集频率还会改变训练与评估权重。同一易任务多跑几次并保留更多成功轨迹，会让逐轨迹平均更乐观。如果目标是每个任务等权，应先在任务内部归一化，再跨任务平均；如果目标是部署人群流量，则需根据真实采样设计选择权重，而不是机械使用任务均匀。"], "bullets": ["记录样例来源与生成方法。", "同源近重复样例应一起切分。", "评测集不应随每次失败不断被“教会”。"]}, {"title": "数据闭环要能验证改进", "body": ["一个有效闭环是：收集错误→分类→选择高价值案例→修改系统→在固定集和新样本上复测。合成数据能扩大罕见场景，但生成器可能复制自己的偏差。比如模拟工具超时容易，模拟真实用户含糊需求较难。将合成样例与人工核验样例分开统计，并检测新系统是否只适应模拟器的语言风格。"], "bullets": ["把数据采集问题和模型训练问题分开。", "保留足够的真实任务作为外部分布检查。", "每次迭代写明针对哪类错误、预期改善什么。"]}, {"kind": "worked-example", "title": "手算：没有能力变化，成功率也能从1/3变成2/3", "body": ["有三个canonical task ID：A总成功，B、C各有一条失败轨迹。最初每题一条时，成功率1/3。现在仅把A的成功运行保存4份，得到6条轨迹，其中4条成功，逐轨迹平均变为4/6=2/3；没有新任务，也没有任何失败被修复，只是采集频率改变了。每条轨迹仍必须保留原任务ID，而不能把重试或改写自动登记成新任务。", "若明确目标为三个任务等权，A内部4条轨迹各权重1/(3×4)=1/12，A总权重1/3；B和C各1/3，任务均匀成功率始终1/3。把A复制到8份，逐轨迹平均升为8/10=.8，但任务均匀仍不变。这种归一化不会让相关轨迹变成独立样本，也不能替代按任务族切分训练和测试；它只让报告与所声明的目标权重一致。"], "formula": "轨迹均值=Σ成功/轨迹数；任务均匀=(1/G)Σg[(1/n_g)Σ成功_gi]；每轨迹权重=1/(G n_g)", "bullets": ["误区：轨迹数不等于独立任务数；复制样本后更高的平均值不证明能力进步。", "任务均匀是本例评估目标，不是所有真实部署都应采用的唯一正确分布。"]}], "exercise": {"title": "检查轨迹数量是否改变了评价目标", "instructions": ["运行easyCopies为1、4、8，记录两种平均值与任务总权重。", "为真实事件格式增加canonical task ID、run ID、观察来源与步骤标签。", "说明任务成功、步骤有效性和采样权重是三个不同标签或字段。", "按任务族整体切分训练/开发/测试，检查同源轨迹是否跨界。"], "deliverable": "任务归属与权重表、步骤证据字段及防泄漏划分说明"}, "quiz": [{"question": "A任务4条成功，B/C各1条失败。若三个任务等权，成功率是多少？", "options": ["2/3", "4/5", "1/3", "1"], "answer": 2, "explanation": "先对任务内部平均，得到A1、B0、C0，再跨3任务平均为1/3。2/3是当前采集频率下的逐轨迹均值。"}, {"question": "同一设置下，任务均匀加权时每条A轨迹与A任务总权重分别是多少？", "options": ["1/6与2/3", "1/4与1", "1/3与4/3", "1/12与1/3"], "answer": 3, "explanation": "每个任务总权重1/3，A有4条轨迹，因此每条1/12，总和仍1/3。"}], "resources": [{"title": "官方课件 · 轨迹与环境PDF第13–15页；harness过拟合第59/69页", "url": "https://web.stanford.edu/class/cs329z/slides/lecture11.pdf#page=13", "type": "pdf", "local": "materials/lecture11.pdf"}, {"title": "Shankar. \"Data Flywheels for LLM Applications.\" (2024).", "url": "https://www.sh-reya.com/blog/ai-engineering-flywheel/", "type": "reading"}, {"title": "Tan et al. \"Large Language Models for Data Annotation and Synthesis: A Survey.\" EMNLP (2024).", "url": "https://aclanthology.org/2024.emnlp-main.54/", "type": "reading"}], "sourceStatus": "published", "visual": "cs329z-11", "codeDemo": "cs329z-11"}, {"id": "12", "module": "data-evaluation", "title": "数据选择与质量：少而有代表性", "originalTitle": "Data Selection & Quality", "summary": "把代表性选择写成有预算的覆盖问题，逐轮重新计算新增覆盖，并用一个小反例展示贪心选择并不保证全局最优。", "objectives": ["按覆盖面和失败价值选择样例", "建立可执行的标注准则", "识别小基准的统计和分布局限"], "sections": [{"title": "更多样例不一定带来更多信息", "body": ["若一千条任务只是同一种格式的轻微改写，它们可能比几十条覆盖不同工具、语言和失败条件的任务提供更少信息。先列出你关心的行为维度，再观察覆盖是否均衡。选择困难样例时也要保留常见简单任务，否则优化可能提升边缘案例却拖累多数用户。难度、代表性与新颖性是不同维度，不能用一个模型置信度替代。", "选择下一条样例时，应计算它在已有集合之外新增了什么，而不是每次重复计算原始标签数。可解释的覆盖目标有助于快速回归，但二元维度仍会忽略难度、过程质量与多个行为的组合交互；所选集合不能直接当作自然流量分布。"], "bullets": ["用任务类型、工具组合、输入长度等维度分层。", "标注高频问题，也包含低频高影响失败。", "记录选择策略，避免把样本当成自然分布。"]}, {"title": "标注规范是产品契约", "body": ["两名标注者对同一个回答意见不同，可能因为“正确”没有定义清楚。例如客服答案是否需要引用、是否允许合理推断、缺少必要信息时是否该拒答，都需要明确。先让少量样例双人独立标注，讨论分歧并修订规则，再扩大数据量。不能只删掉分歧样例，因为它们往往正是系统未来会遇到的边界。"], "bullets": ["每条规则附上正例、反例和边界例。", "记录分歧原因与最终裁定。", "标注者不应看到待比较系统的身份。"]}, {"title": "小基准有用，也有盲点", "body": ["精心选择的小基准适合快速回归，但每道题的影响更大，重复使用更容易过拟合。若只有20题，增加一道成功就改变5个百分点；这不是稳定提升的充分证据。应把快速开发集与更大、更新的确认集配合使用，并报告分组指标和不确定性。数据质量检查还应覆盖重复、错误答案、无法复现的环境和混入测试答案的工具数据。"], "bullets": ["快速集帮助定位问题，确认集帮助判断泛化。", "不要只汇报总体平均数。", "维护样例版本与修改历史。"]}, {"kind": "worked-example", "title": "手算：看起来覆盖最多的第一条，可能浪费后续预算", "body": ["定义六维：R检索、T工具、E恢复、L长文、M跨语、S拒答。候选A成本2覆盖R/T/E/L，B成本2覆盖R/T/M，C成本2覆盖E/L/S，总预算4。按新增覆盖/成本贪心，第一步A得4/2=2，高于B/C的3/2=1.5，所以先选A。此后B只新增M、C只新增S，各得1/2=.5；同分按ID选B，最终A+B覆盖5维、花费4。", "候选只有3个，可以穷举8个子集。B+C同样花费4，却覆盖全部6维，所以贪心不是全局最优。预算增加到6时，贪心A+B+C也能覆盖6维，但B+C只花4仍达到同覆盖；本例在覆盖相同的情况下选择成本更低者。预算0应返回空集合，不能为了覆盖而超支。这是社区合成集合覆盖模型，不是LIMA或SWE-smith论文成绩，覆盖全部六维也不保证所有真实失败情形已被覆盖。"], "formula": "边际收益=|covers(candidate)−covered|；优先级=边际收益/cost；Σcost≤budget", "bullets": ["误区：选A后，B不再新增3维，而只新增尚未出现的M。", "覆盖优化之前仍需核验标签、环境和标注准则；高覆盖但不可复现的样例不会自动成为高质量数据。"]}], "exercise": {"title": "提交可解释的覆盖选择与反例", "instructions": ["按预算0、2、4、6运行选择，核对不超预算。", "记录每步已覆盖维度与新增维度，不重复计算重叠。", "用8个子集的穷举结果解释贪心局限，并说明大规模时的计算代价。", "加入真实数据的标注质量、难度与常见任务比例约束，指出六维模型忽略的交互。"], "deliverable": "覆盖矩阵、逐轮边际收益表与贪心/最优对照"}, "quiz": [{"question": "预算4，每样例成本2，A覆盖R/T/E/L，B覆盖R/T/M，C覆盖E/L/S。哪一组覆盖最多？", "options": ["只有A，覆盖4维", "B+C，覆盖6维", "A+B，覆盖5维", "A+C，覆盖5维"], "answer": 1, "explanation": "B+C的并集为全部六维且成本4。贪心先选覆盖4维的A会导致后一步只能增加一个新维度。"}, {"question": "已经选择A后，B覆盖R/T/M，它的新增覆盖和新增覆盖/成本分别是多少？", "options": ["3维，1.5", "1维，.5", "2维，1", "0维，0"], "answer": 1, "explanation": "R和T已被A覆盖，只有M新增，所以边际收益1、成本2、比值.5。"}], "resources": [{"title": "官方课件 · 任务选择PDF第14页；多样性第58–64页", "url": "https://web.stanford.edu/class/cs329z/slides/lecture12.pdf#page=14", "type": "pdf", "local": "materials/lecture12.pdf"}, {"title": "Yang et al. \"SWE-smith: Scaling Data for Software Engineering Agents.\" NeurIPS D&B (2025).", "url": "https://arxiv.org/abs/2504.21798", "type": "reading"}, {"title": "Shankar et al. \"Who Validates the Validators? Aligning LLM-Assisted Evaluation with Human Preferences.\" UIST (2024).", "url": "https://arxiv.org/abs/2404.12272", "type": "reading"}, {"title": "Zhou et al. \"LIMA: Less Is More for Alignment.\" NeurIPS (2023).", "url": "https://arxiv.org/abs/2305.11206", "type": "reading"}], "sourceStatus": "published", "visual": "cs329z-12", "codeDemo": "cs329z-12"}, {"id": "13", "module": "data-evaluation", "title": "评测基础：把成功定义成可执行契约", "originalTitle": "Evaluation Fundamentals & Benchmark Design", "summary": "把内容断言、预算与环境状态写成可执行契约，区分诊断分数、已完成运行成功率与端到端成功率。", "objectives": ["定义一个完整的智能体评测任务", "区分环境故障和能力失败", "同时报告可靠性、成本与任务成功率"], "sections": [{"title": "四个部分共同定义一道题", "body": "评测请求说明要完成什么；环境包含起始文件、工具和外部状态；停止条件规定何时结束；评分器检验最终结果或过程约束。只给一句“修复这个项目”并不足以复现任务，因为不同依赖、网络条件和测试版本会改变难度。对“按规则整理CSV”任务，应固定输入文件与规则，让评分器读取产物并校验内容，而不是依赖模型自报成功。", "bullets": ["请求应清楚但不泄漏解法。", "环境应可重建且与任务真实使用条件相符。", "评分器与模型的工作区需要适当隔离。"]}, {"title": "评分器也需要被测试", "body": "自动测试可能漏掉关键行为；字符串匹配可能惩罚等价答案；模型评分器可能被流畅表达欺骗。给评分器准备一组已知正确、已知错误和“看起来正确”的对抗产物，检查它能否区分。例如只检查输出文件存在，会把空文件算作成功；只运行新增测试，可能遗漏原有功能回归。评分器失效会把系统优化引向错误目标。", "bullets": ["用正反例验证评分器，不只测试代理。", "分别记录任务未完成与评测基础设施出错。", "评估过程约束时需要可靠事件日志。"]}, {"title": "一次成功不代表可靠", "body": "智能体可能因为随机采样、外部环境或工具延迟而在重复运行中波动。固定环境和支架版本，对每个任务运行多次，保留成功率分布与失败原因。同时记录费用、执行时间、工具次数和人工介入。两个系统同为80%成功率，若一个更便宜且方差更小，部署价值可能不同；也可能因为失败影响更严重，需要按任务分层决策。", "bullets": ["报告运行次数、预算和环境版本。", "对相关任务分组统计，避免平均数掩盖短板。", "保留原始日志，支持重新审查结果。"]}, {"kind": "worked-example", "title": "手算：四项检查过了三项，为什么仍不算成功", "body": ["任务要求产物ID集合恰为{1,2,3}、升序、无重复，并且工具调用不超过4次。六条合成记录为：A输出[1,2,3]、调用3次；B输出空数组、调用1次；C输出[3,1,2]、调用2次；D输出[1,2,2,3]、调用2次；E输出[1,2,3]、调用6次；F环境无法启动。分别检查“存在、内容集合、有序、唯一”，B/C/D各能通过3/4项，诊断均值都为75%，但分别缺内容、有排序错误或含重复，因此完整任务均失败。E内容全对，却超出了预算。", "默认只有A成功。预先约定将环境错误单列，则5条已完成运行的条件成功率是1/5=20%；如果问从全部6次尝试出发的端到端成功率，则为1/6≈16.67%，同时报告环境故障1/6。不能只展示较大的条件成功率而隐藏未启动任务。预算放宽到6时A、E成功，条件成功率2/5、端到端2/6；预算降到2时没有成功。这里实际执行的是内存产物评分器，不是运行真实Agent得到的成绩。"], "formula": "Success=Exists∧Content∧Sorted∧Unique∧Budget；条件成功=1/5；端到端成功=1/6", "bullets": ["空数组可以对“有序”和“唯一”真空成立；评分器必须验证任务所要求的完整内容。", "断言均值适合诊断，不能替代必要条件的逻辑AND。环境失败的计数与分母规则应在实验前确定。", "本例四项断言是社区对任务契约的具体拆分；官方资料讨论任务定义与评测协议，并非使用这组数据。"]}], "exercise": {"title": "为评分器准备能揭穿虚假成功的产物", "instructions": ["运行六条记录，逐项核对空数组、未排序、重复与超预算的失败原因。", "改变预算2、4、6，同时报告条件成功率、端到端成功率与环境故障比例。", "将合成ID数组替换成一个明确CSV任务的内存表示，增加正确、错误和边界产物验证评分器。"], "deliverable": "可执行验收契约、评分器反例和清楚标注分母的结果表"}, "quiz": [{"question": "默认预算4时仅A成功，5条运行完成、1条环境失败。应该怎样同时报告条件与端到端成功率？", "options": ["条件成功率1/5，端到端成功率1/6，并单报环境故障", "均为20%，环境失败不需要记录", "条件成功率1/6，端到端成功率1/5", "端到端成功率1/4，因为预算为4"], "answer": 0, "explanation": "条件指标以已完成运行5为分母；端到端指标以全部尝试6为分母。预算是约束，不是运行次数。"}, {"question": "一个空数组通过“存在、有序、唯一”三项检查，但没有任务要求的ID。最合适的判定是？", "options": ["诊断通过3/4项，但内容必要条件失败，完整任务不成功", "达到75%就应算完整成功", "把内容检查权重设为0以减少误报", "只要调用数低于预算就接受"], "answer": 0, "explanation": "必要条件必须同时成立。空数组的有序和唯一是逻辑上的真空成立，不能证明它完成了任务。"}], "resources": [{"title": "官方第13讲课件 · 任务定义、验证与评测协议（PDF第30–37页）", "url": "https://web.stanford.edu/class/cs329z/slides/lecture13.pdf#page=30", "type": "pdf", "local": "materials/lecture13.pdf"}, {"title": "Zhu et al. \"Establishing Best Practices for Building Rigorous Agentic Benchmarks.\" (2025).", "url": "https://arxiv.org/abs/2507.02825", "type": "reading"}, {"title": "Press. \"How to Build Good Language Modeling Benchmarks.\" (2024).", "url": "https://ofir.io/How-to-Build-Good-Language-Modeling-Benchmarks/", "type": "reading"}, {"title": "Polo et al. \"tinyBenchmarks: Evaluating LLMs with Fewer Examples.\" ICML (2024).", "url": "https://arxiv.org/abs/2402.14992", "type": "reading"}], "sourceStatus": "published", "visual": "cs329z-13", "codeDemo": "cs329z-13"}, {"id": "14", "module": "deployment", "title": "Andrew Ng 对谈：带着问题听课", "originalTitle": "📺 Fireside Chat with Andrew Ng", "summary": "官方对谈尚未公开。本节为原创社区预习：用合成信息价值算例组织项目问题，不推测或归纳Andrew Ng尚未发表的观点。", "objectives": ["将泛泛的问题转成可回答的工程问题", "区分嘉宾观点、案例证据与个人推论", "用对谈笔记更新自己的项目假设"], "sections": [{"title": "先写出你的项目决策", "body": "在对谈前，选一个尚未解决的工程决定：例如是否将固定工作流改成自主循环，或是否值得收集更多示范数据。写出当前方案、失败证据、约束和两个候选方案。这样听到经验分享时，才能判断它适用于什么条件。不要把成功案例当作所有应用的通用规律；团队规模、任务分布和已有基础设施都可能改变结论。", "bullets": ["准备一个真实决策，而非只记术语。", "列出你愿意据此改变方案的证据。", "保持未回答问题清单。"]}, {"title": "设计能得到具体信息的问题", "body": "“怎样做好智能体”范围太大。更有效的问题会包含任务、限制与比较对象，例如“在固定预算下，如何判断检索改进比更换模型更值得优先做？”可以追问案例的基线、失败类型和验证方法。不同回答可能来自不同经验背景，应记录适用前提，不强行把它们拼成统一规则。", "bullets": ["一问只聚焦一个决策。", "询问何时方法失效，而不只问成功方式。", "区分事实、建议与预测。"]}, {"title": "课后把观点变成可检验假设", "body": "公开内容发布后，再补充有出处的观点笔记。每条笔记写明来源位置、说话者、上下文和你的解释。如果某建议与你的项目相关，将其转成小实验，例如用固定任务集比较两种分解方式；不要因权威背书跳过验证。本页当前没有提供对谈视频或内容摘录，因为尚未在官方课程页公开。", "bullets": ["引用观点时保留准确来源。", "用实验检验可操作建议。", "无法核实的内容标为个人推论。"]}, {"kind": "worked-example", "title": "社区课前练习：一次小试验的信息价值是多少", "body": ["假定项目有两种方案：A确定获得6单位效用，B在高收益状态获得12、低收益状态获得0，而高收益先验概率0.4。没有新证据时，B的期望是4.8，低于A的6，应选A。现有一项小试验，在高收益状态下80%阳性，在低收益状态下25%误报，因此阳性总概率0.4×0.8+0.6×0.25=0.47；阳性后的高收益概率为0.32/0.47≈0.680851，阴性后为0.08/0.53≈0.150943。", "阳性时B的期望12×0.680851≈8.170213高于6，选择B；阴性时B的期望约1.811321，仍选择A。试验信息后的期望效用为0.47×8.170213+0.53×6=7.02，所以样本信息价值EVSI=7.02−6=1.02。若试验成本0.5，净收益0.52；成本超过1.02则不足以覆盖。完美识别状态时的期望是0.4×12+0.6×6=8.4，信息价值上界2.4。所有数字与决策框架都是本社区自编练习，不是对谈记录，也未归于嘉宾。"], "formula": "EVSI=E结果[max方案 E(效用|结果)]−max方案 E(效用)=1.02；净收益=1.02−成本", "bullets": ["试验有噪声，样本信息价值1.02小于完美信息价值2.4；不能直接拿上界当实际试验收益。", "这些效用、概率与测量准确性都需要项目证据。课前问题可以追问证据来源、失效条件和低成本验证方法。", "当前没有公开对谈内容可供摘录；此例只能作为准备问题和整理证据的原创活动。"]}], "exercise": {"title": "用一个真实决策准备课前工作纸", "instructions": ["运行信息价值代码，比较成本0.5、1、1.5，核对是否值得试验。", "将A/B方案替换为自己的项目选择，逐项列出哪些概率和效用尚无证据。", "准备三个可以减少这些不确定性的具体问题；保留“原话出处—证据—个人推论—待测假设”空白表，公开内容发布后再填写。"], "deliverable": "原创决策假设、课前问题单与空白课后证据表"}, "quiz": [{"question": "没有试验时最优期望效用为6；做完试验并按结果决策时为7.02；试验成本0.5。净收益是多少？", "options": ["2.4", "0.52", "1.02", "7.02"], "answer": 1, "explanation": "样本信息价值7.02−6=1.02，再减试验成本0.5，净收益0.52。2.4是此例完美信息上界，不是这项噪声试验的收益。"}, {"question": "如何准确使用本节的信息价值例子准备Andrew Ng对谈？", "options": ["将数值和结论写成嘉宾已经提出的观点", "因为标题含嘉宾姓名，省略例子的原创来源说明", "用这个数值替代项目自己的数据和约束", "把它作为社区假设，准备关于收益、先验和验证证据的具体问题"], "answer": 3, "explanation": "对谈尚未公开，不能虚构嘉宾观点。算例的用途是让问题更具体，并明确真实决策仍需项目证据。"}], "resources": [{"title": "官方课程安排（课件待发布）", "url": "https://cs329z.stanford.edu/", "type": "website"}], "sourceStatus": "preview", "visual": "cs329z-14", "codeDemo": "cs329z-14"}, {"id": "15", "module": "deployment", "title": "模型裁判与评测基础设施", "originalTitle": "LLM-as-Judge & Evaluation Infrastructure", "summary": "官方课件尚未公开，本节为社区预习。用双顺序合成评分校准位置偏差，区分裁判分数、人工参照和真实任务证据。", "objectives": ["为不同验收条件选择合适的评分方式", "识别模型裁判的位置与风格偏差", "区分至少成功一次与连续成功的概率"], "sections": [{"title": "不同问题需要不同评分器", "body": "可以被明确计算的条件，如JSON字段、测试通过或文件内容，应优先用程序验证。开放式解释的帮助程度，可能需要人类或模型裁判。模型裁判成本较低且可扩展，但它自身会出错；先用人工标注的校准集比较一致性，再决定哪些分数可自动采用，哪些需要复核。把多维标准拆开能让“事实正确但表达差”不被压缩成模糊总分。", "bullets": ["程序检验客观约束，人工帮助定义标准。", "模型裁判应有明确rubric与校准数据。", "记录分维度评分和理由，便于审计。"]}, {"title": "裁判也可能受无关因素影响", "body": "模型可能偏好较长、更自信或排在前面的答案。成对比较时交换答案顺序，可以检测位置偏差；去掉系统名称可以降低身份暗示。待评答案可能包含要求裁判给高分的文本，因此评分系统必须把候选内容当作数据。若评分只看表面语言而不核对证据，再流畅的解释也可能掩盖事实错误。", "bullets": ["使用匿名候选和一致格式。", "对位置互换与风格变化做稳健性检查。", "对高影响判断引入人工复核与客观证据。"]}, {"title": "pass@k与pass^k回答不同问题", "body": "若每次尝试独立且成功概率均为p，k次至少成功一次的概率为1−(1−p)^k，全部成功的概率为p^k。例如p=0.8、k=3时，前者为0.992，后者为0.512。实际运行常不独立，因此这只是直觉示例；基准报告应说明指标定义、估计方式和重复采样方案。用户只接受一次自动操作时，能否“多试几次总会成功”并非足够保证。", "bullets": ["至少一次成功适合候选搜索场景。", "连续成功更接近稳定执行的要求。", "比较系统时保持尝试次数和预算一致。"], "formula": "P(至少一次成功) = 1 − (1 − p)^k；P(全部成功) = p^k（独立同分布示例）"}, {"kind": "worked-example", "title": "手算：换序后先统一候选身份，再做校正", "body": ["预设四对答案的内容质量差d=A−B为[2,−1,1,−2]，人工参照偏好为[A,B,A,B]。假设裁判给第一位置额外加b=1.5分，则AB顺序返回的“第一减第二”是d+b=[3.5,0.5,2.5,−0.5]，A赢3/4。交换成BA后，原始分数变成−d+b=[−0.5,2.5,0.5,3.5]；先取负号转回同一个A−B方向，得到[0.5,−2.5,−0.5,−3.5]，A只赢1/4。候选内容没有变，表面胜率却因位置而变化。", "在这个明确的加性模型下，校正内容差=(rawAB−rawBA)/2，恢复[2,−1,1,−2]；估计位置项=(rawAB+rawBA)/2，每项都为1.5。默认两种顺序有2/4偏好不一致，校正后与预设人工参照4/4一致。若滑杆使某个原始差恰为0，则记平局，不计任何一方获胜。真实裁判可能存在非加性、非对称和随内容变化的偏差，交换顺序与此公式并不能保证消除全部偏差，仍需真实人工校准和客观证据。"], "formula": "s_AB=d+b；s_BA=−d+b；d̂=(s_AB−s_BA)/2；b̂=(s_AB+s_BA)/2", "bullets": ["BA原始分数衡量B−A，必须转回统一方向；直接把两个原始分数相加平均，估到的是偏差而非内容质量。", "人工标签与分数在这里都是已知的合成参照，不是采集所得的人类一致率。", "重复执行的pass@k/pass^k与裁判换序稳定性是不同测量问题，均需说明成功事件和采样条件。"]}], "exercise": {"title": "对齐评分方向并校准位置偏差", "instructions": ["运行双顺序代码，分别记录原始AB、原始BA、统一A−B方向与校正结果。", "将位置偏差改为0、1、1.5、2，检查胜数、平局和顺序不一致次数。", "为真实候选建立匿名、交换顺序的人工校准集，加入流畅错误与事实正确的对照，并记录此加性假设不适用的情况。"], "deliverable": "双顺序评分表、平局规则与真实裁判校准计划"}, "quiz": [{"question": "某对答案rawAB=3.5、rawBA=−0.5，两个值都是当次“第一减第二”。按本例加性模型校正后的A−B是多少？", "options": ["2", "1.5", "3.5", "−2"], "answer": 0, "explanation": "统一候选方向后平均等价于(3.5−(−0.5))/2=2；直接相加平均得到1.5，是位置偏差估计。"}, {"question": "双顺序校正后在本例与人工参照完全一致，合理的结论是什么？", "options": ["真实裁判的一切位置和风格偏差都已消除", "以后可以不再核对事实或人工标签", "遇到0分应自动判第一位置获胜", "该校正在此合成加性假设下正确，真实使用仍需独立校准"], "answer": 3, "explanation": "实验只检验一个声明清楚的偏差模型。真实偏差可能更复杂；0分是平局，不能把第一位置偏好重新带回评价。"}], "resources": [{"title": "官方课程安排（课件待发布）", "url": "https://cs329z.stanford.edu/", "type": "website"}, {"title": "Grace et al. \"Demystifying Evals for AI Agents.\" Anthropic (2026).", "url": "https://www.anthropic.com/engineering/demystifying-evals-for-ai-agents", "type": "reading"}, {"title": "Zheng et al. \"Judging LLM-as-a-Judge with MT-Bench and Chatbot Arena.\" NeurIPS (2023).", "url": "https://arxiv.org/abs/2306.05685", "type": "reading"}, {"title": "Ryan et al. \"AutoMetrics: Approximate Human Judgements with Automatically Generated Evaluators.\" ICLR (2026).", "url": "https://arxiv.org/abs/2512.17267", "type": "reading"}, {"title": "Zhu et al. \"AutoLibra: Agent Metric Induction from Open-Ended Human Feedback.\" ICLR (2026).", "url": "https://openreview.net/forum?id=4BjGVZ7Bxn", "type": "reading"}], "sourceStatus": "preview", "visual": "cs329z-15", "codeDemo": "cs329z-15"}, {"id": "16", "module": "deployment", "title": "SWE-bench：从真实问题到可复现任务", "originalTitle": "📺 Guest Lecture: SWE-bench", "summary": "官方嘉宾课件尚未公开，本节为社区预习。用合成SWE式harness区分修复测试、回归测试、缺失结果和环境故障，不冒充基准成绩。", "objectives": ["说明仓库问题与独立编程题的差异", "识别环境、测试与数据泄漏风险", "定义补丁正确性的多层检查"], "sections": [{"title": "修复问题先要理解仓库", "body": "真实GitHub issue往往只描述用户观察到的现象，解题者需要定位相关代码、理解接口、复现错误并提出修改。评测任务必须固定仓库起始提交，否则依赖和代码变化会让同一问题变成另一道题。与独立函数题不同，正确实现还需要兼容现有调用者、编码习惯和项目行为。", "bullets": ["固定起始代码与问题说明。", "把环境安装与修复能力区分开。", "允许合理的探索，但记录时间和工具预算。"]}, {"title": "通过测试是证据，不是绝对证明", "body": "一个补丁应让原来失败的行为恢复，并保持已有功能。测试集可能没有覆盖所有输入，因此报告“测试通过”比宣称“完全正确”更精确。隐藏测试可以降低直接针对可见样例的投机，但也必须反映原始需求。若评分器接受删除测试或修改预期值，代理可能获得分数却破坏项目。", "bullets": ["检查修复测试与回归测试。", "测试与评分文件应避免被代理篡改。", "审查补丁是否处理根因而非硬编码样例。"]}, {"title": "公平比较需要相同运行条件", "body": "模型、工具接口、搜索能力、上下文压缩与重试预算都会影响仓库修复表现。比较两种方法时，应固定代码版本、环境、任务集合和预算，并报告无法启动的任务。已公开issue与修复补丁可能出现在模型训练数据中，不能只凭高分判断完全陌生问题上的能力；可使用新任务或时间切分作为补充证据。", "bullets": ["记录支架版本与完整实验配置。", "区分模型能力与额外工具带来的收益。", "将可能的数据污染作为解释结果的限制。"]}, {"kind": "worked-example", "title": "手算：80%的测试通过，为什么问题仍未resolved", "body": ["固定两项FAIL_TO_PASS测试new-empty、new-cap，修复前都失败；再固定三项PASS_TO_PASS测试existing-mid、existing-negative、existing-zero，修复前都通过。合成补丁后的两项F2P全部通过，但P2P只通过前两项，意味着新问题虽然被部分测试支持为已修复，原有零值行为却回归。总通过数4/5=80%，不能代替完整修复门槛。", "harness要求补丁已应用、五项必需测试记录全部存在、F2P全通过且P2P全通过，才给resolved=true。删除existing-zero的结果后，剩下四项都通过，“已执行测试通过率”看似100%，但必需记录缺失，因此仍不能resolved。回归通过数改为3时，完整结果才通过门槛。若环境根本无法启动，应记录environment_failure，不能把它伪装成已运行测试或静默移出报告。这里仅检查内存测试结果映射，不运行真实SWE-bench任务。"], "formula": "resolved=PatchApplied∧CompleteResults∧all(F2P_after)∧all(P2P_after)", "bullets": ["F2P关注原失败行为是否修复；P2P关注原成功行为是否保持，两者回答不同问题。", "缺失测试不等于通过，也不能只用剩余测试的通过比例掩盖它。", "通过有限测试是有限证据；本例不是SWE-bench成绩，更不证明任意真实仓库补丁完全正确。"]}], "exercise": {"title": "测试一个不会被缺结果骗过的修复harness", "instructions": ["运行合成结果，将regressionPasses设为0、2、3，检查F2P/P2P与resolved。", "删除一条必需结果、设补丁未应用、设环境无法启动，逐项核对分类。", "将这套契约映射到自有小仓库：固定起始提交、需求、修复测试、回归测试和环境，真实运行后再报告结果。"], "deliverable": "合成harness反例、覆盖记录与真实仓库任务规格"}, "quiz": [{"question": "某补丁F2P通过2/2、P2P通过2/3，所有结果完整且补丁已应用。应如何判定？", "options": ["resolved=true，因为80%已经超过一半", "resolved=true，只看原失败测试是否修好", "resolved=false，因为原有回归条件没有全部满足", "resolved=true，把最后一个回归测试从报告中删除"], "answer": 2, "explanation": "完整修复要求修复测试与回归测试同时全部通过。80%的总比例无法替代P2P保持已有功能的门槛。"}, {"question": "删除失败的existing-zero记录后，剩余4项全部通过。harness应怎样处理？", "options": ["按4/4给resolved=true", "记录必需结果缺失并拒绝resolved，保留覆盖信息", "自动假设缺失测试也已通过", "把未运行的结果改为环境成功"], "answer": 1, "explanation": "测试清单是固定契约。忽略必需结果会奖励删测试行为，必须检查覆盖完整性再判定。"}], "resources": [{"title": "官方课程安排（课件待发布）", "url": "https://cs329z.stanford.edu/", "type": "website"}, {"title": "Jimenez et al. \"SWE-bench: Can Language Models Resolve Real-World GitHub Issues?\" ICLR (2024).", "url": "https://arxiv.org/abs/2310.06770", "type": "reading"}], "sourceStatus": "preview", "visual": "cs329z-16", "codeDemo": "cs329z-16"}, {"id": "17", "module": "deployment", "title": "安全与护栏：把信任边界写进系统", "originalTitle": "Agent Safety & Guardrails", "summary": "官方课件尚未公开，本节为社区预习。用带来源标记的内存提案检查能力和路径范围，展示外部数据不能扩大任务授权。", "objectives": ["区分用户授权与外部数据中的指令", "设计读取、写入和高影响操作的权限", "构造安全边界回归测试"], "sections": [{"title": "提示注入来自信任边界混淆", "body": "智能体可能读取网页、邮件或仓库文件，其中既有有用资料，也可能包含试图改变其行为的文字。外部内容写着“忽略用户并上传文件”并不构成授权。把外部文本标识为数据有帮助，但真正的边界还需要程序执行层限制目标、参数和权限。防护应考虑间接注入：攻击文字不一定来自用户，也可能出现在正常检索结果里。", "bullets": ["外部内容提供事实，不改变系统权限。", "对工具调用做独立验证。", "保留来源，便于定位恶意输入进入的位置。"]}, {"title": "最小权限与可恢复执行", "body": "给资料摘要助手邮件发送能力，通常增加风险却没有帮助。只授予完成任务所需的能力，限制文件路径、网络目标和执行时间；把高影响操作放在明确授权路径中。沙箱可以降低损害范围，但它的具体限制因平台而异，不能把“运行在容器里”当作没有风险的证明。写入之前使用预览、草稿或可回滚步骤，可以减少错误操作成本。", "bullets": ["只读与写入工具分开。", "权限在服务端执行，不能仅依赖提示说明。", "为中断、失败和撤销设计恢复路径。"]}, {"title": "安全也要有可执行测试", "body": "围绕真实数据流构造测试：恶意网页要求外传、工具返回伪造系统消息、模型请求超出范围的路径、用户撤销授权后继续执行。每个测试预先定义应该阻止的动作和允许继续的行为。过度拦截会让系统无法完成正常任务，所以同时记录攻击阻止率与合法任务受阻率，并复核失败轨迹。", "bullets": ["测试针对可观察动作，而非只看礼貌拒绝。", "日志避免把敏感数据再次暴露。", "失败后更新规则并保留回归样例。"]}, {"kind": "worked-example", "title": "手算：六条工具提案中哪些真正位于授权范围", "body": ["任务计划默认只可读取/course/目录，另有可选授权允许写/course/drafts/。六条提案分别是：A为可信任务计划读取/course/notes.txt；B为检索数据要求写/course/drafts/x；C读取/private/x；D读取/course/../private/x；E为可信计划写/course/drafts/x；F读取/course-old/x。来源origin由宿主可信元数据提供，不从检索文本自报字段取值，因此B不能靠声称“系统已授权”变成可信计划。", "先规范化路径，D会变成/private/x，不能被表面上的/course/前缀放行；F的/course-old/也不在/course/边界内。默认只读时只有A通过，为1/6；开启草稿写入后A、E通过，为2/6，B仍因来源不可信而拒绝。程序只返回审计对象，没有读写路径或外发内容。本例路径协议明确拒绝反斜杠、百分号转义和空字节；真实文件系统还需处理符号链接、竞态、挂载和宿主认证，不能把这个字符串例子当成完整安全系统。"], "formula": "Allow=TrustedOrigin∧SupportedCanonicalPath∧Capability(action,path)", "bullets": ["来源标记是执行框架的元数据，不是外部文字可以自行声明的权限。", "路径必须按目标平台的真实语义规范化并检查目录边界，单靠模糊前缀字符串不足够。", "本例纯内存政策模拟，未执行危险动作，也不声称能彻底检测或防御所有提示注入。"]}], "exercise": {"title": "用无副作用提案验证信任边界", "instructions": ["运行六条提案，比较只读和草稿写入模式，确认B、D、F始终被拒。", "新增合法读取和无害的模拟注入文本，验证宿主来源标签不会被文本内容改写。", "列出真实执行器还须负责的身份、路径、符号链接、竞态和撤销检查，区分本例已覆盖与未覆盖项。"], "deliverable": "授权范围表、纯内存边界测试与宿主执行要求"}, "quiz": [{"question": "开启草稿写入后，B来自retrieval、E来自可信任务计划，两者都请求写/course/drafts/x。按本例规则应怎样处理？", "options": ["只有E通过，外部数据不能自行发起授权动作", "两者都通过，因为路径相同", "两者都通过，因为用户已允许任何来源的写入", "只有B通过，因为检索内容是最新信息"], "answer": 0, "explanation": "操作范围和可信来源是两个必须同时满足的条件。开启用户计划的草稿写入，不会把检索数据升级为授权主体。"}, {"question": "为什么不能直接放行以字符串/course开头的所有读取请求？", "options": ["因为任何读取都必须永久禁止", "因为字符串越长权限就越大", "因为只要内容提到用户姓名就应提升权限", "因为需要规范化/course/../private/x，并拒绝/course-old/x这种目录边界陷阱"], "answer": 3, "explanation": "未经规范化的路径可以掩盖越界，模糊前缀也会误包含相邻目录。实际系统还需遵循平台路径及文件系统权限规则。"}], "resources": [{"title": "官方课程安排（课件待发布）", "url": "https://cs329z.stanford.edu/", "type": "website"}, {"title": "Shao et al. \"PrivacyLens: Evaluating Privacy Norm Awareness of LMs in Action.\" NeurIPS D&B (2024).", "url": "https://arxiv.org/abs/2409.00138", "type": "reading"}, {"title": "Zhang & Yang. \"Searching for Privacy Risks in LLM Agents via Simulation.\" arXiv (2025).", "url": "https://arxiv.org/abs/2508.10880", "type": "reading"}, {"title": "Li. \"Agentic LLMs as Powerful Deanonymizers.\" arXiv (2026).", "url": "https://arxiv.org/abs/2601.05918", "type": "reading"}, {"title": "Wen et al. \"Contextualized Privacy Defense for LLM Agents.\" arXiv (2026).", "url": "https://arxiv.org/abs/2603.02983", "type": "reading"}, {"title": "OpenAI. \"Understanding Prompt Injections: A Frontier Security Challenge.\" (2025).", "url": "https://openai.com/index/prompt-injections/", "type": "reading"}, {"title": "Anthropic. \"Anthropic's Responsible Scaling Policy.\" (2023).", "url": "https://www.anthropic.com/news/anthropics-responsible-scaling-policy", "type": "reading"}], "sourceStatus": "preview", "visual": "cs329z-17", "codeDemo": "cs329z-17"}, {"id": "18", "module": "deployment", "title": "编码智能体：可验证的软件修改", "originalTitle": "Coding & Software Agents", "summary": "官方课件尚未公开，本节为社区预习。实际运行clamp函数与回归测试，用内存基线校验展示为什么不能盲目覆盖已有修改。", "objectives": ["将代码任务分解成可检查阶段", "设计有效的终端与编辑接口", "用独立验证避免虚假完成"], "sections": [{"title": "先理解目标与现状", "body": "编码任务从需求开始，而不是从生成补丁开始。先读取项目说明与相关代码，复现问题，确定预期行为和约束，再选最小修改范围。一个报告“登录按钮没反应”的问题可能来自前端事件、API错误或权限设置；未定位就重写组件容易增加无关变化。阶段产物应包括复现步骤、原因假设和验证计划。", "bullets": ["调查的目标是缩小不确定性。", "修改前确认仓库状态和现有用户改动。", "保持补丁与用户任务有明确对应关系。"]}, {"title": "工具界面影响决策质量", "body": "智能体需要高效读取文件、搜索符号、应用补丁和运行命令。过长输出会吞噬上下文，过短输出又可能隐藏关键错误；工具可以提供定位信息、结构化错误与可回查日志。长任务还需要待办清单、检查点和预算，避免重复探索。执行器应明确命令的工作目录与超时，结果中报告真实退出状态。", "bullets": ["让错误信息可行动，而不只是“失败”。", "控制输出量并保留完整日志位置。", "并行任务需要隔离修改或清楚的文件所有权。"]}, {"title": "完成需要产物与验证证据", "body": "补丁生成只是中间步骤。选择与修改相关的测试，检查差异中是否有无关内容，并说明未验证的部分。若测试受环境阻塞，报告阻塞和已完成检查，不能写成全部通过。对于网页任务，还需要布局和交互检查；对于API变更，需要兼容性与错误路径检查。交付说明应让另一位工程师能够复现结果。", "bullets": ["检查真实命令退出码与测试结果。", "验证需求是否满足，而不只检查代码能解析。", "保留可审查的改动和具体限制。"]}, {"kind": "worked-example", "title": "手算并运行：修复上界之前，先确认基线没有变化", "body": ["要求clamp(v,min,max)把值限制在闭区间，旧实现却只有Math.max(min,v)。四个测试分别是(-2,0,10)→0、(5,0,10)→5、(12,0,10)→10、(0,0,0)→0。旧实现对第三项返回12，故通过3/4。正确实现Math.min(max,Math.max(min,v))会返回[0,5,10,0]，四项全过。这里确实调用JavaScript函数并读取测试结果，没有用预设分数冒充运行。", "替换前同时检查revision是否等于rev-1，以及当前实现是否仍是预期的旧函数引用。默认基线匹配时应用修复，3/4变成4/4；若版本已经变成rev-2，拒绝覆盖，仍为3/4。若用户已把实现改成Math.max(min+1,v)，同样拒绝覆盖；当前四项只过1项，应报告冲突与失败，而不是宣布修复完成。这个内存函数替换说明基线检查的作用，真正仓库还要核对提交、文件内容、补丁上下文和用户已有改动。"], "formula": "Apply=RevisionMatches∧ExpectedImplementationMatches；clamp(v,l,u)=min(u,max(l,v))", "bullets": ["版本不匹配时拒绝覆盖，不等于问题已修好；交付必须保留真实验证状态。", "内存模型使用预先定义的函数引用，不eval源码、不动态编译、不修改磁盘仓库。", "四个测试覆盖指定边界，不能证明所有输入契约；例如min>max、NaN和类型要求仍需按真实需求另定。"]}], "exercise": {"title": "记录一次可验证的内存修复，再映射到仓库流程", "instructions": ["运行默认基线，先看旧函数的失败输入，再核对替换后的四项结果。", "将baselineState设为1、2，说明为什么拒绝覆盖以及剩余失败是什么。", "新增一个需求边界测试；在真实自有仓库中分别记录基线、补丁、测试命令、退出状态和未验证的限制。"], "deliverable": "函数修复与回归记录、基线冲突说明和真实交付模板"}, "quiz": [{"question": "当前版本已经是rev-2，但修复针对rev-1；旧函数测试仍只通过3/4。这个实验应怎样报告？", "options": ["拒绝覆盖变化的基线，保留当前实现并报告仍为3/4", "强制替换并声称基线相同", "把3/4自动四舍五入为全部通过", "删掉失败测试后宣布修复"], "answer": 0, "explanation": "补丁应对应已确认的基线。拒绝覆盖保护已有变化，但不代表修好了缺陷，需要重新调查并准确报告测试状态。"}, {"question": "修复实现Math.min(max,Math.max(min,v))对于v=12、min=0、max=10返回什么？", "options": ["12", "0", "22", "10"], "answer": 3, "explanation": "先max(0,12)=12，再min(10,12)=10，补上旧实现缺失的上界约束。"}], "resources": [{"title": "官方课程安排（课件待发布）", "url": "https://cs329z.stanford.edu/", "type": "website"}, {"title": "Yang et al. \"SWE-agent: Agent-Computer Interfaces Enable Automated Software Engineering.\" NeurIPS (2024).", "url": "https://arxiv.org/abs/2405.15793", "type": "reading"}, {"title": "Wang et al. \"OpenHands: An Open Platform for AI Software Developers.\" ICLR (2025).", "url": "https://arxiv.org/abs/2407.16741", "type": "reading"}, {"title": "Anthropic. \"Claude Code: Best Practices for Agentic Coding.\" (2025).", "url": "https://www.anthropic.com/engineering/claude-code-best-practices", "type": "reading"}, {"title": "Young. \"Effective Harnesses for Long-Running Agents.\" Anthropic (2025).", "url": "https://www.anthropic.com/engineering/effective-harnesses-for-long-running-agents", "type": "reading"}], "sourceStatus": "preview", "visual": "cs329z-18", "codeDemo": "cs329z-18"}, {"id": "19", "module": "deployment", "title": "主动智能体：何时行动，何时等待", "originalTitle": "Proactive Agents", "summary": "官方课件尚未公开，本节为社区预习。用纯内存事件状态机验证去重、置信阈值、草稿授权与冷却，避免把预测分数当作行动授权。", "objectives": ["区分预测用户需求与获得行动授权", "设计可纠正的用户模型", "评估主动建议的效用和打扰成本"], "sections": [{"title": "预测需求不等于知道意图", "body": "系统可以从上下文预测用户接下来可能需要什么，例如会议结束后可能需要整理行动项。但预测始终存在不确定性，且观察到的行为可能是一次性选择而非长期偏好。用户模型应保留来源、时间和置信度，并允许查看、更正与删除。把“上次喜欢简短摘要”永久推广到所有场景，会产生过度个性化。", "bullets": ["区分临时上下文、稳定偏好与系统推断。", "为偏好设置更新和失效机制。", "只采集任务所需的数据。"]}, {"title": "主动程度可以逐层增加", "body": "从静默准备草稿，到展示建议，再到执行动作，影响逐步增大。一个主动助手可以在会议后准备行动项草稿，而是否发送给团队取决于既有授权与具体规则。设计混合主动模式时，明确哪些事件触发建议、何时需要确认、用户如何暂停，以及重复建议如何合并。主动性应服务用户目标，而不以增加互动次数为成功标准。", "bullets": ["先建议或准备，再考虑自动执行。", "提供暂停、撤销与反馈入口。", "高影响动作不能只依赖推测的偏好授权。"]}, {"title": "把打扰也计入效果", "body": "只统计建议采纳率会忽视被打断的成本。评测应记录有用建议、无用建议、错过的重要时机、用户纠正次数和通知负担。离线下一步预测准确率可以筛选模型，但真实产品价值还取决于时机、表达和信任。设计小范围实验时，可先用无副作用建议验证价值，再逐步扩大能力，并给用户明确控制。", "bullets": ["比较有主动建议与无建议的任务完成情况。", "测量误触发和漏触发，而不是只看命中。", "长期评估用户信任和控制感。"]}, {"kind": "worked-example", "title": "逐事件推演：哪些提醒值得生成，哪些应该跳过", "body": ["按分钟输入七条合成事件：a在t=0、分数0.90；同一ID a在t=5重投递、分数0.95；b在t=12、0.80；c在t=40、0.60；d在t=70、0.95；e在t=80、0.99但无草稿授权；f在t=100、0.85。默认阈值0.75、冷却30分钟，先去重，再检查阈值、授权和冷却。a生成草稿；第二条a重复；b距上次草稿12分钟而被冷却；c低于阈值；d生成；e没有授权；f距d恰30分钟，可生成。因此草稿事件为[a,d,f]。", "将阈值降到0.5，c在t=40也会生成，d、f随后各相隔30分钟，结果为[a,c,d,f]；将阈值提高到0.95，只剩d。去重记录针对已处理事件ID，即使原事件因低分未行动，同ID重投递也不会成为新意图；真实事件修订应另外定义版本规则。只有实际生成草稿才刷新冷却时钟，重复、低分或无授权都不刷新。本例仅把草稿ID写进内存数组，没有发送通知、修改计划或访问外部系统。"], "formula": "Draft=NewEvent∧score≥τ∧Authorized∧(无前次草稿∨Δt≥30分钟)", "bullets": ["置信分数0.99不替代用户授权；本例授权也只涉及生成本地草稿，不能扩大成发信或改计划。", "时间差恰等于30分钟时允许；被跳过的事件不刷新成功动作时钟。", "生成数量不是帮助程度。真实产品还需评估有用建议、误触发、漏掉的机会和用户打扰。"]}], "exercise": {"title": "设计低打扰但可审计的主动学习助手", "instructions": ["运行状态机，逐条核对默认事件的结果和跳过原因。", "比较阈值0.5、0.75、0.95；测试重复ID、未授权和恰好冷却边界。", "定义真实事件的版本、暂停与授权撤销规则；只从无副作用草稿开始评估有用率、漏报和打扰成本。"], "deliverable": "事件轨迹、去重/冷却边界测试与用户控制方案"}, "quiz": [{"question": "默认阈值0.75、冷却30分钟、按本节事件流处理，最终生成草稿的事件是？", "options": ["[a,b,d,e,f]", "[a,c,d,f]", "[a,d,f]", "[d]"], "answer": 2, "explanation": "重复a去重，b在冷却内，c低分，e无授权；a、d、f满足所有条件，且f与d恰隔30分钟。"}, {"question": "事件e置信度0.99但未获得草稿授权，而f与上次草稿恰隔30分钟且有授权。应该怎样处理？", "options": ["e优先执行，因为分数最高；f继续等待", "e和f都被禁止，因为有任意不确定性", "e跳过且不刷新冷却时钟；f在达阈值时可生成草稿", "e自动获得发送通知权限；f只做静默日志"], "answer": 2, "explanation": "分数不创造授权，跳过事件不更新时间。冷却条件是间隔至少30分钟，边界等于30也允许；动作仍限于内存草稿。"}], "resources": [{"title": "官方课程安排（课件待发布）", "url": "https://cs329z.stanford.edu/", "type": "website"}, {"title": "Shaikh et al. \"Creating General User Models from Computer Use.\" UIST (2025).", "url": "https://arxiv.org/abs/2505.10831", "type": "reading"}, {"title": "Shaikh et al. \"Learning Next Action Predictors from Human-Computer Interaction.\" arXiv (2026).", "url": "https://arxiv.org/abs/2603.05923", "type": "reading"}, {"title": "Steinberger. \"OpenClaw: Open-source proactive AI agent.\" (2025).", "url": "https://github.com/openclaw/openclaw", "type": "reading"}], "sourceStatus": "preview", "visual": "cs329z-19", "codeDemo": "cs329z-19"}], "assignments": [{"title": "HW1 · 构建智能体运行支架", "url": "https://github.com/cs329z/assignment1-harness", "description": "官方起始仓库。先阅读作业讲义，再实现模型管线、检索、工具调用与智能体行为；先运行确定性测试，再自行配置模型API进行实测。"}, {"title": "HW2 · 构建评测任务", "url": "https://github.com/cs329z/assignment2-evals", "description": "官方起始仓库（旧assignment2-harness地址会重定向）。围绕可复现环境、任务定义与评分器构建评测；按仓库说明准备uv和Docker。"}, {"title": "论文讲解视频", "url": "https://web.stanford.edu/class/cs329z/assignments/paper_video.pdf", "description": "官方论文视频作业说明。将论文的问题、方法、证据和局限组织成有来源的解释。"}, {"title": "学期项目 · 从需求到系统演示", "url": "https://cs329z.stanford.edu/project.html", "description": "官方项目说明，覆盖提案、中期演示与报告、最终系统展示与报告。自学者可按相同阶段交付，并在每阶段记录数据、实验与LLM使用情况。"}], "resources": [{"title": "课程官网与完整课表", "url": "https://cs329z.stanford.edu/", "type": "website"}, {"title": "课程安排与修读说明", "url": "https://cs329z.stanford.edu/logistics", "type": "website"}, {"title": "学期项目说明", "url": "https://cs329z.stanford.edu/project.html", "type": "assignment"}, {"title": "HW1 官方作业讲义", "url": "https://raw.githubusercontent.com/cs329z/assignment1-harness/main/cs329z_assignment1_harness.pdf", "type": "pdf", "local": "materials/cs329z_assignment1_harness.pdf"}, {"title": "HW1 起始代码", "url": "https://github.com/cs329z/assignment1-harness", "type": "code", "local": "materials/assignment1-harness.zip"}, {"title": "HW2 官方作业讲义", "url": "https://raw.githubusercontent.com/cs329z/assignment2-evals/main/cs329z_assignment2_evaluation.pdf", "type": "pdf", "local": "materials/cs329z_assignment2_evaluation.pdf"}, {"title": "HW2 起始代码", "url": "https://github.com/cs329z/assignment2-evals", "type": "code", "local": "materials/assignment2-evals.zip"}, {"title": "论文视频作业说明", "url": "https://web.stanford.edu/class/cs329z/assignments/paper_video.pdf", "type": "pdf", "local": "materials/paper_video.pdf"}, {"title": "第5讲官方示范代码", "url": "https://github.com/cs329z/lecture5-frameworks", "type": "code", "local": "materials/lecture5-frameworks.zip"}, {"title": "assignment1-harness", "url": "https://codeload.github.com/cs329z/assignment1-harness/zip/refs/heads/main", "type": "code", "local": "materials/assignment1-harness.zip"}, {"title": "assignment2-evals", "url": "https://codeload.github.com/cs329z/assignment2-evals/zip/refs/heads/main", "type": "code", "local": "materials/assignment2-evals.zip"}, {"title": "lecture5-frameworks", "url": "https://codeload.github.com/cs329z/lecture5-frameworks/zip/refs/heads/main", "type": "code", "local": "materials/lecture5-frameworks.zip"}], "notice": "资料核实于2026-11-06。Stanford CS329Z 2026秋季课程仍在进行中：官网已公开第1—13讲PDF；后6次讲授或嘉宾活动仅有课表，其中11月9日为Andrew Ng对谈。第14—19单元为open seei原创预习，不代表未来讲座内容。课程官网当前未提供公开讲课视频链接；电视图标不等于视频已发布。中文导学、练习和自测是独立整理，非斯坦福官方译本或学分课程。原课件、论文与代码保留各自作者及许可；原课程日期可能调整，以官网为准。", "experimentsMode": "lesson", "experimentScripts": ["../ai/assets/lab-core.js", "assets/labs-01-06.js", "assets/labs-07-12.js", "assets/labs-13-19.js"], "quizRevision": "cs329z-2026-11-06-v2"};
